async function _sbFindTeamMemberById(id) {
  if (!id) return null;
  try { return await supabaseDb.selectById(_sbTeamMembersTable(), id); } catch {}
  const rows = await _sbSelectTeamMembersRows();
  return (rows || []).find((row) => String(_sbGet(row, ["id", "ID"]) ?? "") === String(id)) || null;
}

function _sbExtractAllowedPages(row) {
  return normalizePages(_sbSplitValues(_sbValueForLabel(row, "Allowed Pages")));
}

function _sbAccountPayload(row, fallbackUsername = "") {
  const allowedUI = expandAllowedForUI(_sbExtractAllowedPages(row));
  return {
    name: _sbString(_sbValueForLabel(row, "Name")) || fallbackUsername || "",
    username: _sbString(_sbValueForLabel(row, "Name")) || fallbackUsername || "",
    department: _sbString(_sbValueForLabel(row, "Department")) || "",
    position: _sbString(_sbValueForLabel(row, "Position")) || "",
    photoUrl: _sbExtractUrl(_sbValueForLabel(row, "Profile picture")) || "",
    phone: _sbString(_sbValueForLabel(row, "Phone")) || "",
    email: _sbString(_sbValueForLabel(row, "Email")) || "",
    employeeCode: _sbString(_sbValueForLabel(row, "Employee Code")) || null,
    filesMedia: [],
    passwordSet: !!_sbString(_sbValueForLabel(row, "Password")),
    allowedPages: allowedUI,
    source: "supabase",
  };
}

async function _sbGetAdminRow() {
  const rows = await _sbSelectTeamMembersRows();
  const list = Array.isArray(rows) ? rows : [];
  return list.find((row) => norm(_sbString(_sbValueForLabel(row, "Name"))) === "admin") ||
    list.find((row) => norm(_sbString(_sbValueForLabel(row, "Position"))).includes("admin")) ||
    list.find((row) => norm(_sbString(_sbValueForLabel(row, "Name"))).includes("admin")) || null;
}

async function _sbVerifyAdminPassword(inputPassword) {
  const pwd = String(inputPassword || "").trim();
  if (!pwd) return false;
  const row = await _sbGetAdminRow();
  if (!row) return false;
  const stored = _sbString(_sbValueForLabel(row, "Password"));
  return !!stored && String(stored) === pwd;
}

function _sbColumnForIncomingField(keys, incomingName) {
  return _sbFindKey(keys, [incomingName, _sbLabelForColumn(incomingName)]);
}

function _sbBuildWriteRowFromFields(fields = {}, rows = []) {
  const keys = _sbAllColumnKeys(rows).filter((key) => !_sbNonEditableColumn(key));
  const row = {};
  for (const [incomingName, rawValue] of Object.entries(fields || {})) {
    if (_sbCanon(incomingName) === "allowedpages") continue;
    if (_sbCanon(incomingName) === "svschools") continue;
    const actual = _sbColumnForIncomingField(keys, incomingName);
    if (!actual) continue;
    const value = String(rawValue ?? "").trim();
    row[actual] = value || null;
  }
  return _uaAttachSvSchoolLinkColumns(row, keys, fields, rows);
}

function _sbBool(value, fallback = false) {
  if (typeof value === "boolean") return value;
  if (typeof value === "number") return value !== 0;
  const raw = String(value ?? "").trim().toLowerCase();
  if (!raw) return fallback;
  if (["true", "t", "yes", "y", "1", "on", "enabled"].includes(raw)) return true;
  if (["false", "f", "no", "n", "0", "off", "disabled"].includes(raw)) return false;
  return fallback;
}

function _sbRestFilterValue(value) {
  return encodeURIComponent(String(value ?? ""));
}

function _sbRestStringList(values = []) {
  const clean = (Array.isArray(values) ? values : [])
    .map((value) => String(value ?? "").trim())
    .filter(Boolean)
    .map((value) => `"${value.replace(/"/g, '\\"')}"`);
  return encodeURIComponent(clean.join(","));
}

function _sbSerializeAppPage(row = {}) {
  const id = _sbGet(row, ["id", "page_id", "ID"]);
  const pageKeyRaw = _sbString(_sbGet(row, ["page_key", "pageKey"])) || "";
  const pageNameRaw = _sbString(_sbGet(row, ["page_name", "pageName", "name"])) || "";
  const routePathRaw = _sbString(_sbGet(row, ["route_path", "routePath"])) || "";
  const mailKey = norm(pageKeyRaw);
  const mailName = norm(pageNameRaw);
  const mailRoute = norm(routePathRaw);
  const isMailPage =
    ["messages", "message", "emails", "email", "mail", "massage"].includes(mailKey) ||
    ["messages", "message", "emails", "email", "mail", "massage"].includes(mailName) ||
    mailRoute === "/messages" || mailRoute === "/emails";
  return {
    id: String(id ?? ""),
    pageId: String(id ?? ""),
    pageKey: pageKeyRaw,
    pageName: isMailPage ? "Mail" : pageNameRaw,
    routePath: routePathRaw,
    routePattern: _sbString(_sbGet(row, ["route_pattern", "routePattern"])) || "",
    moduleName: _sbString(_sbGet(row, ["module_name", "moduleName"])) || "General",
    parentPageKey: _sbString(_sbGet(row, ["parent_page_key", "parentPageKey"])) || "",
    sortOrder: Number(_sbGet(row, ["sort_order", "sortOrder"]) || 100),
    isActive: _sbBool(_sbGet(row, ["is_active", "isActive"]), true),
    isAssignable: _sbBool(_sbGet(row, ["is_assignable", "isAssignable"]), true),
    visibleInSidebar: _sbBool(_sbGet(row, ["visible_in_sidebar", "visibleInSidebar"]), true),
  };
}

async function _sbSelectAppPages({ assignableOnly = true, activeOnly = true } = {}) {
  if (!_sbTeamMembersEnabled()) return [];
  const params = ["select=*", "order=sort_order.asc", "limit=1000"];
  if (activeOnly) params.push("is_active=eq.true");
  if (assignableOnly) params.push("is_assignable=eq.true");
  const rows = await supabaseDb.request(`/app_pages?${params.join("&")}`);
  return (Array.isArray(rows) ? rows : []).map(_sbSerializeAppPage).filter((page) => page.id && page.pageKey && page.pageName);
}

function _sbLegacyAllowedPagesFromAppPage(page = {}) {
  const key = String(page?.pageKey || page?.page_key || "").trim();
  const name = String(page?.pageName || page?.page_name || "").trim();
  const map = {
    "current-orders": "Current Orders",
    "operations-orders": "Requested Orders",
    "maintenance-orders": "Maintenance Orders",
    "shopping-cart": "Create New Order",
    stocktaking: "Stocktaking",
    products: "Products",
    proposals: "Proposals",
    "product-proposals": "Proposals",
    "orders-review": "Orders Review",
    expenses: "Expenses",
    "expenses-users": "Expenses Users",
    b2b: "B2B",
    tasks: "Tasks",
    messages: "Mail",
    message: "Mail",
    emails: "Mail",
    email: "Mail",
    mail: "Mail",
    massage: "Mail",
    "user-access-data": USER_ACCESS_PAGE_NAME,
  };
  const mapped = map[key];
  if (mapped) return [mapped];
  return normalizePages([name]);
}

function _sbAllowedPagesFromPageAccessRows(rows = []) {
  const names = [];
  for (const row of rows || []) {
    if (!_sbBool(_sbGet(row, ["is_enabled", "isEnabled"]), false)) continue;
    const page = _sbSerializeAppPage(row);
    const mapped = _sbLegacyAllowedPagesFromAppPage(page);
    for (const name of mapped) if (name) names.push(name);
  }
  return normalizePages(names);
}

function _sbPageAccessSummaryFromRows(rows = []) {
  const enabledRows = (rows || []).filter((row) => _sbBool(_sbGet(row, ["is_enabled", "isEnabled"]), false));
  const adminRows = enabledRows.filter((row) => String(_sbGet(row, ["access_level", "accessLevel"]) || "user").toLowerCase() === "admin");
  return {
    allowedPages: expandAllowedForUI(_sbAllowedPagesFromPageAccessRows(enabledRows)),
    accessCount: enabledRows.length,
    adminCount: adminRows.length,
  };
}

async function _sbSelectPageAccessViewForMember(teamMemberId) {
  const id = String(teamMemberId || "").trim();
  if (!_sbTeamMembersEnabled() || !id) return [];
  const rows = await supabaseDb.request(`/team_member_page_access_view?select=*&team_member_id=eq.${_sbRestFilterValue(id)}&order=sort_order.asc&limit=1000`);
  return Array.isArray(rows) ? rows : [];
}

async function _sbSelectAllPageAccessView() {
  if (!_sbTeamMembersEnabled()) return [];
  const rows = await supabaseDb.request('/team_member_page_access_view?select=*&order=sort_order.asc&limit=5000');
  return Array.isArray(rows) ? rows : [];
}

async function _sbSelectRawPageAccessForMember(teamMemberId) {
  const id = String(teamMemberId || "").trim();
  if (!_sbTeamMembersEnabled() || !id) return [];
  const rows = await supabaseDb.request(`/team_member_page_access?select=*&team_member_id=eq.${_sbRestFilterValue(id)}&limit=1000`);
  return Array.isArray(rows) ? rows : [];
}

async function _sbResolveAllowedPagesForTeamMember(row = {}) {
  const memberId = String(_sbGet(row, ["id", "ID"]) ?? "").trim();
  const fallback = _sbExtractAllowedPages(row);
  if (!memberId) return fallback;
  try {
    const accessRows = await _sbSelectPageAccessViewForMember(memberId);
    if (Array.isArray(accessRows) && accessRows.length) {
      return _sbAllowedPagesFromPageAccessRows(accessRows);
    }
  } catch (error) {
    console.warn("[user-access] page-access lookup failed, using legacy allowed-pages column:", error?.message || error);
  }
  return fallback;
}

async function _sbAccountPayloadWithAccess(row, fallbackUsername = "") {
  const payload = _sbAccountPayload(row, fallbackUsername);
  const allowedNormalized = await _sbResolveAllowedPagesForTeamMember(row);
  const allowedUI = expandAllowedForUI(allowedNormalized);
  payload.allowedPages = allowedUI;
  return { accountPayload: payload, allowedNormalized, allowedUI };
}

function _sbGroupPageAccessRowsByMember(rows = []) {
  const map = new Map();
  for (const row of rows || []) {
    const id = String(_sbGet(row, ["team_member_id", "teamMemberId"]) || "").trim();
    if (!id) continue;
    if (!map.has(id)) map.set(id, []);
    map.get(id).push(row);
  }
  return map;
}

function _sbAttachPageAccessSummary(member, rows = []) {
  const summary = _sbPageAccessSummaryFromRows(rows || []);
  const fallbackAllowed = Array.isArray(summary.allowedPages) && summary.allowedPages.length
    ? summary.allowedPages
    : expandAllowedForUI(_sbExtractAllowedPages({ allowed_pages: fieldValueFromLikeMember(member, "Allowed Pages") }));
  member.pageAccessSummary = {
    allowedPages: fallbackAllowed,
    accessCount: summary.accessCount || (fallbackAllowed || []).filter((name) => ALL_PAGES.includes(name)).length,
    adminCount: summary.adminCount || 0,
  };
  return member;
}

function fieldValueFromLikeMember(member = {}, fieldName = "") {
  const field = (member?.fields || []).find((f) => String(f?.label || "") === String(fieldName || ""));
  return field?.value || "";
}

function _sbNormalizePageAccessEntries(entries = []) {
  return (Array.isArray(entries) ? entries : [])
    .map((entry) => {
      const pageId = String(entry?.pageId || entry?.page_id || entry?.id || "").trim();
      const pageKey = String(entry?.pageKey || entry?.page_key || "").trim();
      const accessLevel = String(entry?.accessLevel || entry?.access_level || "user").trim().toLowerCase() === "admin" ? "admin" : "user";
      const isEnabled = _sbBool(entry?.isEnabled ?? entry?.is_enabled ?? entry?.enabled, false);
      return { pageId, pageKey, accessLevel, isEnabled };
    })
    .filter((entry) => entry.pageId || entry.pageKey);
}

async function _sbPageAccessPayloadForMember(teamMemberId) {
  const pages = await _sbSelectAppPages({ assignableOnly: true });
  const accessRows = await _sbSelectRawPageAccessForMember(teamMemberId).catch(() => []);
  const byPageId = new Map((accessRows || []).map((row) => [String(_sbGet(row, ["page_id", "pageId"]) ?? ""), row]));
  const items = pages.map((page) => {
    const access = byPageId.get(String(page.pageId || page.id));
    return {
      ...page,
      accessId: String(_sbGet(access || {}, ["id", "access_id", "accessId"]) ?? ""),
      accessLevel: String(_sbGet(access || {}, ["access_level", "accessLevel"]) || "user").toLowerCase() === "admin" ? "admin" : "user",
      isEnabled: access ? _sbBool(_sbGet(access, ["is_enabled", "isEnabled"]), false) : false,
    };
  });
  return { pages: items, summary: _sbPageAccessSummaryFromRows(items.map((x) => ({ ...x, page_key: x.pageKey, page_name: x.pageName, is_enabled: x.isEnabled, access_level: x.accessLevel }))) };
}

async function _sbSavePageAccessForMember(teamMemberId, entries = [], { teamMemberName = "", grantedBy = "" } = {}) {
  const memberId = String(teamMemberId || "").trim();
  if (!memberId) {
    const err = new Error("Missing team member ID.");
    err.status = 400;
    throw err;
  }
  const pages = await _sbSelectAppPages({ assignableOnly: true });
  const pagesById = new Map(pages.map((page) => [String(page.pageId || page.id), page]));
  const pagesByKey = new Map(pages.map((page) => [String(page.pageKey), page]));
  const cleanEntries = _sbNormalizePageAccessEntries(entries);
  const existing = await _sbSelectRawPageAccessForMember(memberId).catch(() => []);
  const existingByPageId = new Map((existing || []).map((row) => [String(_sbGet(row, ["page_id", "pageId"]) ?? ""), row]));
  const results = [];

  for (const entry of cleanEntries) {
    const page = (entry.pageId && pagesById.get(entry.pageId)) || (entry.pageKey && pagesByKey.get(entry.pageKey));
    if (!page) continue;
    const pageId = String(page.pageId || page.id);
    const current = existingByPageId.get(pageId);
    const body = {
      team_member_id: memberId,
      team_member_name: teamMemberName || null,
      page_id: Number(pageId),
      access_level: entry.accessLevel,
      is_enabled: !!entry.isEnabled,
      granted_by: grantedBy || null,
    };

    if (current) {
      const accessId = String(_sbGet(current, ["id", "access_id", "accessId"]) || "").trim();
      if (!accessId) continue;
      const rows = await supabaseDb.request(`/team_member_page_access?id=eq.${_sbRestFilterValue(accessId)}`, {
        method: "PATCH",
        headers: { Prefer: "return=representation" },
        body: {
          team_member_name: body.team_member_name,
          access_level: body.access_level,
          is_enabled: body.is_enabled,
          granted_by: body.granted_by,
        },
      });
      if (Array.isArray(rows) && rows[0]) results.push(rows[0]);
      continue;
    }

    if (!entry.isEnabled) continue;
    const created = await supabaseDb.request('/team_member_page_access', {
      method: "POST",
      headers: { Prefer: "return=representation" },
      body,
    });
    if (Array.isArray(created) && created[0]) results.push(created[0]);
  }

  return results;
}

async function _sbQueryAllTeamMembersForUserAccess() {
  const rows = await _sbSelectTeamMembersRows();
  const editableFields = await _uaEnrichEditableFieldsForSupabase(_sbOrderedEditableFieldsFromRows(rows), rows);
  const accessRows = await _sbSelectAllPageAccessView().catch((error) => {
    console.warn("[user-access] failed to load page-access summary:", error?.message || error);
    return [];
  });
  const accessByMember = _sbGroupPageAccessRowsByMember(accessRows);
  const members = (rows || []).map((row) => {
    const member = _sbSerializeTeamMemberRow(row, editableFields);
    const id = String(member?.id || "").trim();
    return _sbAttachPageAccessSummary(member, accessByMember.get(id) || []);
  });
  members.sort((a, b) => {
    const da = String(a.department || "").localeCompare(String(b.department || ""));
    if (da) return da;
    return String(a.name || "").localeCompare(String(b.name || ""));
  });
  const departmentRows = await _sbSelectDepartmentRows().catch((error) => {
    console.warn("[user-access] optional department folders table unavailable:", error?.message || error);
    return [];
  });
  const map = new Map();
  for (const row of departmentRows || []) {
    const name = _sbDepartmentNameFromRow(row);
    if (!name) continue;
    const payload = _sbDepartmentPayload(name, {
      isCustomDepartment: true,
      departmentRecordId: _sbGet(row, ["id", "ID"]),
    });
    if (!map.has(payload.id)) map.set(payload.id, payload);
  }
  for (const member of members) {
    const key = member.departmentKey || _uaDepartmentKey(member.department);
    if (!map.has(key)) map.set(key, _sbDepartmentPayload(member.department || "No Department"));
    const dept = map.get(key);
    dept.members.push(member);
    dept.count += 1;
  }
  return { total: members.length, editableFields, departments: Array.from(map.values()).sort((a, b) => String(a.name || "").localeCompare(String(b.name || ""))), source: "supabase" };
}

// -----------------------------------------------------------------------------
// Supabase Expenses adapter
// -----------------------------------------------------------------------------
function _sbExpensesEnabled() {
  return !!(supabaseDb && supabaseDb.isConfigured && supabaseDb.isConfigured());
}

function _sbExpensesTable() {
  const cfg = supabaseDb.getConfig ? supabaseDb.getConfig() : {};
  return (cfg.expensesTable || process.env.SUPABASE_EXPENSES_TABLE || "expenses").trim() || "expenses";
}

function _sbExpenseNum(value, fallback = 0) {
  if (value === null || typeof value === "undefined" || value === "") return fallback;
  if (typeof value === "number") return Number.isFinite(value) ? value : fallback;
  const raw = String(value || "").trim();
  if (!raw || /^null$/i.test(raw)) return fallback;
  const n = Number(raw.replace(/[^0-9.-]/g, ""));
  return Number.isFinite(n) ? n : fallback;
}

function _sbExpenseText(value) {
  const t = _sbString(value);
  return t && !/^null$/i.test(t) ? t : "";
}

function _sbExpenseDate(value) {
  const raw = _sbExpenseText(value);
  if (!raw) return null;
  const d = new Date(raw);
  if (Number.isNaN(d.getTime())) return raw;
  return d.toISOString().slice(0, 10);
}

function _sbExpenseDateTime(value) {
  const raw = _sbExpenseText(value);
  if (!raw) return null;
  const d = new Date(raw);
  if (Number.isNaN(d.getTime())) return raw;
  return d.toISOString();
}

function _sbExpenseGet(row, aliases = []) {
  return _sbGet(row, aliases);
}

function _sbExpenseMemberIdentityFromTeamRow(row = {}) {
  const name = _sbExpenseText(_sbValueForLabel(row, "Name"));
  const code = _sbExpenseText(_sbValueForLabel(row, "Employee Code"));
  const id = _sbExpenseText(_sbGet(row, ["id", "ID"]));
  const email = _sbExpenseText(_sbValueForLabel(row, "Email"));
  return { id, name, code, email };
}

async function _sbCurrentExpenseMember(req) {
  const username = String(req?.session?.username || "").trim();
  if (!username) return null;
  const row = await _sbFindTeamMemberByName(username).catch(() => null);
  if (!row) return { name: username, code: "", id: "", email: "" };
  return { row, ..._sbExpenseMemberIdentityFromTeamRow(row) };
}

function _sbExpenseMatchesMember(row = {}, member = {}) {
  if (!row || !member) return false;
  const rowName = norm(_sbExpenseGet(row, ["team_member_name", "Team Member", "team_member_raw", "team_member"]));
  const rowUserId = norm(_sbExpenseGet(row, ["user_id", "employee_code", "Employee Code"]));
  const rowEmail = norm(_sbExpenseGet(row, ["email", "Email"]));
  const name = norm(member.name);
  const code = norm(member.code || member.id);
  const email = norm(member.email);
  if (name && rowName && (rowName === name || rowName.includes(name) || name.includes(rowName))) return true;
  if (code && rowUserId && rowUserId === code) return true;
  if (email && rowEmail && rowEmail === email) return true;
  return false;
}

function _sbParseScreenshotEntries(value) {
  const raw = _sbExpenseText(value);
  if (!raw) return [];
  const out = [];
  const add = (name, url) => {
    const cleanUrl = String(url || "").trim();
    if (!cleanUrl) return;
    out.push({ name: String(name || "Receipt").trim() || "Receipt", url: cleanUrl });
  };
  try {
    const parsed = JSON.parse(raw);
    if (Array.isArray(parsed)) {
      parsed.forEach((item, idx) => {
        if (typeof item === "string") add(`Receipt ${idx + 1}`, item);
        else add(item?.name || `Receipt ${idx + 1}`, item?.url || item?.href || item?.publicUrl);
      });
      return out;
    }
    if (parsed && typeof parsed === "object") {
      add(parsed.name || "Receipt", parsed.url || parsed.href || parsed.publicUrl);
      return out;
    }
  } catch {}
  const urlMatches = raw.match(/https?:\/\/[^\s,"'<>]+/gi) || [];
  if (urlMatches.length) {
    urlMatches.forEach((url, idx) => add(`Receipt ${idx + 1}`, url));
    return out;
  }
  // Imported Notion file paths are not public URLs, but keeping the name helps exports/views.
  if (!/^null$/i.test(raw)) out.push({ name: raw.split(/[\\/]/).pop() || "Receipt", url: raw });
  return out;
}

function _sbExpenseOrders(row = {}) {
  const names = _sbSplitValues(_sbExpenseGet(row, ["orders_names", "Orders", "orders_raw"]));
  const urls = _sbSplitValues(_sbExpenseGet(row, ["orders_urls", "orders_url"]));
  return names.map((name, idx) => {
    const label = String(name || "Order").trim() || "Order";
    const url = String(urls[idx] || "").trim();
    const idMatch = label.match(/ORD[-\s]?(\d+)/i) || label.match(/\b(\d{1,6})\b/);
    const orderId = idMatch ? `ORD-${idMatch[1]}` : label;
    return {
      key: `${orderId}:${idx}`,
      orderId,
      orderType: "",
      label,
      trackingGroupId: orderId,
      trackingUrl: url || "",
      relationIds: [],
      receiptEntries: [],
      items: [],
      receiptViewerUrl: url || "",
    };
  });
}

function _sbSerializeExpenseRow(row = {}) {
  const screenshots = _sbParseScreenshotEntries(_sbExpenseGet(row, ["screenshot", "Screenshot", "files_media"]));
  const createdTime =
    _sbExpenseDateTime(_sbExpenseGet(row, ["notion_created_time", "created_at", "Created time"])) ||
    new Date().toISOString();
  return {
    id: String(_sbExpenseGet(row, ["id", "ID"]) ?? ""),
    createdTime,
    date: _sbExpenseDate(_sbExpenseGet(row, ["expense_date", "Date", "date"])) || null,
    reason: _sbExpenseText(_sbExpenseGet(row, ["reason", "Reason"])) || "",
    fundsType: _sbExpenseText(_sbExpenseGet(row, ["funds_type", "Funds Type"])) || "",
    from: _sbExpenseText(_sbExpenseGet(row, ["from_location", "From", "cash_in_from"])) || "",
    to: _sbExpenseText(_sbExpenseGet(row, ["to_location", "To"])) || "",
    kilometer: _sbExpenseNum(_sbExpenseGet(row, ["kilometer", "Kilometer"]), 0),
    cashIn: _sbExpenseNum(_sbExpenseGet(row, ["cash_in", "Cash in"]), 0),
    cashOut: _sbExpenseNum(_sbExpenseGet(row, ["cash_out", "Cash out"]), 0),
    cashInFrom: _sbExpenseText(_sbExpenseGet(row, ["cash_in_from", "from_location", "From"])) || "",
    orders: _sbExpenseOrders(row),
    screenshots,
    screenshotUrl: screenshots[0]?.url || "",
    screenshotName: screenshots[0]?.name || "",
    teamMemberName: _sbExpenseText(_sbExpenseGet(row, ["team_member_name", "Team Member"])),
    userId: _sbExpenseText(_sbExpenseGet(row, ["user_id", "employee_code"])),
    receiptNumber: _sbExpenseText(_sbExpenseGet(row, ["receipt_number", "receiptNumber", "orders_raw", "orders_names"])),
    ordersRaw: _sbExpenseText(_sbExpenseGet(row, ["orders_raw", "orders_names"])),
    source: "supabase",
  };
}

async function _sbSelectExpensesRows({ limit = 5000 } = {}) {
  const rows = await supabaseDb.selectAll(_sbExpensesTable(), {
    limit,
    order: "expense_date.desc,notion_created_time.desc,id.desc",
  });
  const list = Array.isArray(rows) ? rows : [];
  return list.sort((a, b) => {
    const ad = new Date(_sbExpenseGet(a, ["expense_date", "notion_created_time", "created_at"]) || 0).getTime();
    const bd = new Date(_sbExpenseGet(b, ["expense_date", "notion_created_time", "created_at"]) || 0).getTime();
    if (Number.isFinite(ad) && Number.isFinite(bd) && ad !== bd) return bd - ad;
    return Number(_sbExpenseGet(b, ["id"]) || 0) - Number(_sbExpenseGet(a, ["id"]) || 0);
  });
}

async function _sbSelectExpensesForCurrentUser(req) {
  const member = await _sbCurrentExpenseMember(req);
  if (!member) return { member: null, rows: [] };
  const rows = await _sbSelectExpensesRows();
  return { member, rows: rows.filter((row) => _sbExpenseMatchesMember(row, member)) };
}

function _sbExpenseIsSettlementRow(row = {}) {
  const ft = norm(_sbExpenseGet(row, ["funds_type", "Funds Type"]));
  const reason = norm(_sbExpenseGet(row, ["reason", "Reason"]));
  return ft === "settled my account" || reason === "settled my account";
}

function _sbLastSettledInfo(rows = []) {
  let lastSettledAt = null;
  let lastSettledDate = null;
  for (const row of rows || []) {
    if (!_sbExpenseIsSettlementRow(row)) continue;
    const ct = _sbExpenseDateTime(_sbExpenseGet(row, ["notion_created_time", "created_at"]));
    if (!ct) continue;
    if (!lastSettledAt || new Date(ct).getTime() > new Date(lastSettledAt).getTime()) {
      lastSettledAt = ct;
      lastSettledDate = _sbExpenseDate(_sbExpenseGet(row, ["expense_date", "Date"]));
    }
  }
  return { lastSettledAt, lastSettledDate };
}

async function _sbBuildExpenseScreenshotText({ screenshots, screenshotDataUrl, screenshotName, prefix = "expense" } = {}) {
  const files = [];
  if (Array.isArray(screenshots) && screenshots.length) {
    for (let i = 0; i < screenshots.length; i++) {
      const s = screenshots[i] || {};
      const dataUrl = s.dataUrl || s.screenshotDataUrl || "";
      if (!dataUrl) continue;
      const originalName = String(s.name || s.filename || "receipt.png").trim() || "receipt.png";
      const safeName = originalName.replace(/[^a-z0-9._-]/gi, "_");
      const filename = `${prefix}-${Date.now()}-${i}-${Math.random().toString(16).slice(2)}-${safeName}`;
      const url = await uploadToBlobFromBase64(dataUrl, filename);
      files.push({ name: originalName, url });
    }
  }
  if (!files.length && screenshotDataUrl) {
    const originalName = (screenshotName && String(screenshotName).trim()) || `${prefix}-${Date.now()}.png`;
    const safeName = originalName.replace(/[^a-z0-9._-]/gi, "_");
    const filename = `${prefix}-${Date.now()}-${Math.random().toString(16).slice(2)}-${safeName}`;
    const url = await uploadToBlobFromBase64(screenshotDataUrl, filename);
    files.push({ name: originalName, url });
  }
  return files.length ? JSON.stringify(files) : null;
}

