const EXPENSES_FUNDS_TYPE_OPTIONS = [
  "Online Transfer",
  "SWVL",
  "Go Bus",
  "By Bus",
  "ترام",
  "Train",
  "Metro",
  "Indrive",
  "Uber",
  "DiDi",
  "Taxi",
  "توكتوك",
  "نقل",
  "Public transportation",
  "Cash Payment",
  "Meal allowance",
  "مشال",
  "مصروفات",
  "Own car",
  "Settled my account",
];

function _expenseFundsTypeKey(name) {
  return String(name || "")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9\u0600-\u06FF]+/g, "");
}

function _dedupeExpenseFundsTypes(list = []) {
  const options = [];
  const seen = new Set();
  const pushOption = (name) => {
    const raw = String(name || "").trim();
    if (!raw) return;
    const key = _expenseFundsTypeKey(raw);
    if (!key || seen.has(key)) return;
    seen.add(key);
    options.push(raw);
  };
  list.forEach(pushOption);
  return options;
}

async function _sbExpensesTypesOptions() {
  const rows = await _sbSelectExpensesRows();
  const rowOptions = (rows || []).map((row) => _sbExpenseGet(row, ["funds_type", "Funds Type"]));
  return _dedupeExpenseFundsTypes([
    ...EXPENSES_FUNDS_TYPE_OPTIONS,
    ...rowOptions,
  ]);
}

async function _sbExpensesUsersSummary() {
  const rows = await _sbSelectExpensesRows();
  const perUser = new Map();
  for (const row of rows) {
    const name = _sbExpenseText(_sbExpenseGet(row, ["team_member_name", "Team Member", "team_member_raw"])) || "Unknown User";
    const userId = _sbExpenseText(_sbExpenseGet(row, ["user_id", "employee_code"])) || name;
    const key = userId || name;
    if (!perUser.has(key)) perUser.set(key, { id: key, userId: key, name, total: 0, count: 0, lastSettledDate: null });
    const agg = perUser.get(key);
    agg.total += _sbExpenseNum(_sbExpenseGet(row, ["cash_in", "Cash in"]), 0) - _sbExpenseNum(_sbExpenseGet(row, ["cash_out", "Cash out"]), 0);
    agg.count += 1;
    if (_sbExpenseIsSettlementRow(row) && !agg.lastSettledDate) {
      agg.lastSettledDate = _sbExpenseDate(_sbExpenseGet(row, ["expense_date", "Date"]));
    }
  }
  return Array.from(perUser.values()).sort((a, b) => String(a.name || "").localeCompare(String(b.name || "")));
}

function _sbExpenseRowsForMemberId(rows = [], memberId = "") {
  const raw = String(memberId || "").trim();
  const key = norm(raw);
  if (!key) return [];
  return (rows || []).filter((row) => {
    const name = norm(_sbExpenseGet(row, ["team_member_name", "Team Member", "team_member_raw"]));
    const userId = norm(_sbExpenseGet(row, ["user_id", "employee_code"]));
    const id = norm(_sbExpenseGet(row, ["id"]));
    return key === userId || key === name || key === id;
  });
}

function _sbExpenseScreenshotFieldFromEntries(entries = []) {
  const clean = (Array.isArray(entries) ? entries : [])
    .map((entry, index) => ({
      name: String(entry?.name || `Receipt ${index + 1}`).trim() || `Receipt ${index + 1}`,
      url: String(entry?.url || entry?.href || entry?.publicUrl || '').trim(),
    }))
    .filter((entry) => entry.url);
  return clean.length ? JSON.stringify(clean) : null;
}

function _sbStoragePathsFromExpenseScreenshots(entries = []) {
  const cfg = supabaseDb?.getConfig ? supabaseDb.getConfig() : {};
  const base = String(cfg?.url || process.env.SUPABASE_URL || '').trim().replace(/\/+$/, '').replace(/\/rest\/v1\/?$/i, '');
  const bucket = String(cfg?.storageBucket || process.env.SUPABASE_STORAGE_BUCKET || '').trim();
  if (!base || !bucket) return [];
  const publicPrefix = `${base}/storage/v1/object/public/${encodeURIComponent(bucket)}/`;
  const signedPrefix = `${base}/storage/v1/object/sign/${encodeURIComponent(bucket)}/`;
  const out = [];
  for (const entry of Array.isArray(entries) ? entries : []) {
    const rawUrl = String(entry?.url || entry || '').trim();
    if (!rawUrl) continue;
    let path = '';
    if (rawUrl.startsWith(publicPrefix)) {
      path = rawUrl.slice(publicPrefix.length);
    } else if (rawUrl.startsWith(signedPrefix)) {
      path = rawUrl.slice(signedPrefix.length).split('?')[0];
    } else {
      try {
        const u = new URL(rawUrl);
        const publicMarker = `/storage/v1/object/public/${bucket}/`;
        const signedMarker = `/storage/v1/object/sign/${bucket}/`;
        if (u.pathname.includes(publicMarker)) path = u.pathname.split(publicMarker)[1] || '';
        if (!path && u.pathname.includes(signedMarker)) path = u.pathname.split(signedMarker)[1] || '';
      } catch {}
    }
    if (!path) continue;
    try { path = decodeURIComponent(path); } catch {}
    path = path.replace(/^\/+/, '').split('?')[0];
    if (path) out.push(path);
  }
  return Array.from(new Set(out));
}

async function _sbDeleteExpenseStorageForRow(row = {}) {
  if (!supabaseDb?.deleteStorageObjects) return { deleted: 0, skipped: true };
  const entries = _sbParseScreenshotEntries(_sbExpenseGet(row, ["screenshot", "Screenshot", "files_media"]));
  const paths = _sbStoragePathsFromExpenseScreenshots(entries);
  if (!paths.length) return { deleted: 0, paths: [] };
  try {
    await supabaseDb.deleteStorageObjects(paths);
    return { deleted: paths.length, paths };
  } catch (error) {
    console.warn('[supabase] expense storage delete failed:', error?.message || error);
    return { deleted: 0, paths, error: error?.message || String(error) };
  }
}

async function _sbPatchExpenseRowFromUserPayload(expenseId, payload = {}) {
  const current = await supabaseDb.selectById(_sbExpensesTable(), expenseId);
  if (!current) {
    const err = new Error('Expense not found.');
    err.status = 404;
    throw err;
  }

  const nextScreenshots = [];
  const existingUrls = Array.isArray(payload?.screenshotUrls)
    ? payload.screenshotUrls
    : String(payload?.screenshotUrls || '').split(/[\n,]+/);
  existingUrls
    .map((url) => String(url || '').trim())
    .filter(Boolean)
    .forEach((url, index) => nextScreenshots.push({ name: `Receipt ${index + 1}`, url }));

  const newShotText = await _sbBuildExpenseScreenshotText({
    screenshots: Array.isArray(payload?.screenshots) ? payload.screenshots : [],
    screenshotDataUrl: payload?.screenshotDataUrl || '',
    screenshotName: payload?.screenshotName || '',
    prefix: `expense-edit-${expenseId}`,
  });

  try {
    const parsedNew = newShotText ? JSON.parse(newShotText) : [];
    if (Array.isArray(parsedNew)) {
      parsedNew.forEach((entry) => {
        if (entry?.url) nextScreenshots.push({ name: entry.name || 'Receipt', url: entry.url });
      });
    }
  } catch {}

  const uniqueScreenshots = [];
  const seenUrls = new Set();
  for (const shot of nextScreenshots) {
    const url = String(shot?.url || '').trim();
    if (!url || seenUrls.has(url)) continue;
    seenUrls.add(url);
    uniqueScreenshots.push({ name: String(shot?.name || 'Receipt').trim() || 'Receipt', url });
  }

  const row = {
    reason: String(payload?.reason || '').trim(),
    expense_date: String(payload?.date || '').trim() || null,
    funds_type: String(payload?.fundsType || '').trim(),
    from_location: String(payload?.from || '').trim(),
    to_location: String(payload?.to || '').trim(),
    cash_in: _sbExpenseNum(payload?.cashIn, 0),
    cash_out: _sbExpenseNum(payload?.cashOut, 0),
    kilometer: _sbExpenseNum(payload?.kilometer, 0),
    cash_in_from: String(payload?.cashInFrom || '').trim(),
    screenshot: _sbExpenseScreenshotFieldFromEntries(uniqueScreenshots),
  };

  Object.keys(row).forEach((key) => {
    if (row[key] === '') row[key] = null;
  });

  const updated = await supabaseDb.updateById(_sbExpensesTable(), expenseId, row);
  return { current, updated };
}


// -----------------------------------------------------------------------------
// Supabase Orders adapter
// -----------------------------------------------------------------------------
function _sbOrdersEnabled() {
  return !!(supabaseDb && supabaseDb.isConfigured && supabaseDb.isConfigured());
}

function _sbOrdersTable() {
  return (supabaseDb.getConfig().ordersTable || process.env.SUPABASE_ORDERS_TABLE || "orders").trim() || "orders";
}

function _sbOrderNum(value) {
  if (value === null || typeof value === "undefined") return null;
  if (typeof value === "number") return Number.isFinite(value) ? value : null;
  const raw = String(value || "").trim();
  if (!raw || /^null$/i.test(raw)) return null;
  const n = Number(raw.replace(/[^0-9.-]/g, ""));
  return Number.isFinite(n) ? n : null;
}

function _sbOrderText(value) {
  const t = _sbString(value);
  return t && !/^null$/i.test(t) ? t : "";
}

function _sbOrderDate(value) {
  const raw = _sbOrderText(value);
  if (!raw) return null;
  const d = new Date(raw);
  if (Number.isNaN(d.getTime())) return raw;
  return d.toISOString();
}

function _sbOrderGet(row, aliases = []) {
  return _sbGet(row, aliases);
}

function _sbOrderSplitNames(value) {
  return toUniqueStringArray(_sbOrderText(value), { splitComma: true });
}

function _sbOrderStatusColor(status) {
  const s = norm(status);
  if (/archive/.test(s)) return "purple";
  if (/(arrived|delivered|received)/.test(s)) return "green";
  if (/shipped/.test(s)) return "blue";
  if (/rejected/.test(s)) return "red";
  if (/progress/.test(s)) return "yellow";
  if (/supervision/.test(s)) return "orange";
  return "default";
}

function _sbOrderTypeColor(orderType) {
  const s = norm(orderType);
  if (/maintenance/.test(s)) return "purple";
  if (/withdraw/.test(s)) return "red";
  if (/request/.test(s)) return "green";
  return "default";
}

function _sbSerializeOrderRow(row = {}) {
  const id = String(_sbOrderGet(row, ["id", "ID"]) ?? "");
  const orderNum = _sbOrderNum(_sbOrderGet(row, ["order_number", "Order - ID", "Order ID", "order id"]));
  const qtyProgress = _sbOrderNum(_sbOrderGet(row, ["quantity_progress", "Quantity Progress", "quantity", "Quantity", "qty", "Qty"]));
  const qtyRequested = _sbOrderNum(_sbOrderGet(row, ["quantity_requested", "Quantity Requested", "requested_quantity", "Requested Quantity"]));
  const qtyEditedBySupervisor = _sbOrderNum(_sbOrderGet(row, ["quantity_edited_by_supervisor", "Quantity Edited by supervisor", "Quantity Edited by Supervisor", "quantity_edited", "edited_quantity"]));
  // Supabase replacement for the old Notion formula:
  // the original quantity is always Quantity Requested. If the supervisor writes
  // Quantity Edited by supervisor, that edited value becomes the effective qty.
  // The legacy Quantity Progress column is kept only as a fallback for old rows.
  const qtyOriginalBase = roundOrderQty(qtyRequested !== null ? qtyRequested : (qtyProgress !== null ? qtyProgress : 0));
  const qtyBase = roundOrderQty(qtyEditedBySupervisor !== null ? qtyEditedBySupervisor : qtyOriginalBase);
  const qtyReceivedRaw = _sbOrderNum(_sbOrderGet(row, [
    "quantity_received_by_operations",
    "Quantity Received by operations",
    "Quantity Received by Operations",
    "received_quantity",
    "quantity_received",
  ]));
  const qtyRemainingRaw = _sbOrderNum(_sbOrderGet(row, ["quantity_remaining", "Quantity Remaining", "remaining_quantity"]));
  const status = _sbOrderText(_sbOrderGet(row, ["status", "Status"])) || "Pending";

  // Supabase migration note:
  // Some imported rows store empty Notion number columns as 0 instead of null.
  // For a non-zero order, received=0 + remaining=0 usually means "not edited yet", not fully received.
  // The only time we keep remaining=0 with a zero received quantity is when the order is already
  // in a final arrived/delivered/received state.
  const statusKeyForQty = norm(status);
  const isFinalReceivedStatus = /(arrived|delivered|received)/.test(statusKeyForQty);
  const hasBaseQty = Math.abs(Number(qtyBase) || 0) > 1e-9;
  const receivedIsZero = qtyReceivedRaw !== null && Math.abs(Number(qtyReceivedRaw) || 0) < 1e-9;
  const remainingIsZero = qtyRemainingRaw !== null && Math.abs(Number(qtyRemainingRaw) || 0) < 1e-9;
  const remainingEqualsBase = qtyRemainingRaw !== null && Math.abs(roundOrderQty(Number(qtyRemainingRaw) - Number(qtyBase))) < 1e-9;
  const remainingEqualsOriginalBase = qtyRemainingRaw !== null && Math.abs(roundOrderQty(Number(qtyRemainingRaw) - Number(qtyOriginalBase))) < 1e-9;
  const supervisorEditActive = qtyEditedBySupervisor !== null && Math.abs(roundOrderQty(Number(qtyEditedBySupervisor) - Number(qtyOriginalBase))) > 1e-9;
  const noMeaningfulReceivedYet = qtyReceivedRaw === null || Math.abs(Number(qtyReceivedRaw) || 0) < 1e-9;
  const zeroZeroPlaceholder = hasBaseQty && receivedIsZero && remainingIsZero && !isFinalReceivedStatus;
  const zeroReceivedWithBaseRemaining = hasBaseQty && receivedIsZero && remainingEqualsBase;
  const supervisorEditedBeforeOps = supervisorEditActive && noMeaningfulReceivedYet && remainingEqualsOriginalBase;

  let qtyReceived = qtyReceivedRaw;
  let qtyRemaining;
  let quantityReceivedEdited = false;

  if (zeroZeroPlaceholder || zeroReceivedWithBaseRemaining || supervisorEditedBeforeOps) {
    qtyReceived = null;
    qtyRemaining = qtyBase;
  } else if (qtyRemainingRaw !== null) {
    qtyRemaining = roundOrderQty(qtyRemainingRaw);
    quantityReceivedEdited = qtyReceivedRaw !== null && Math.abs(Number(qtyReceivedRaw) || 0) > 1e-9;
  } else {
    const receivedForRemaining = qtyReceivedRaw === null ? 0 : Number(qtyReceivedRaw) || 0;
    qtyRemaining = roundOrderQty((Number(qtyBase) || 0) - receivedForRemaining);
    quantityReceivedEdited = qtyReceivedRaw !== null && Math.abs(Number(qtyReceivedRaw) || 0) > 1e-9;
  }
  const orderType = _sbOrderText(_sbOrderGet(row, ["order_type", "Order Type"])) || null;
  const createdByName = _sbOrderOwnerName(row) ||
    _sbOrderText(_sbOrderGet(row, ["team_member_name", "Teams Members", "teams_members", "Supervisor", "supervisor"])) || "";
  const createdById = _sbOrderOwnerId(row);
  const operationsByName = _sbOrderText(_sbOrderGet(row, ["person_received_by_operations", "Person Received by Operations", "Received by operations"]));
  const spareParts = _sbOrderSplitNames(_sbOrderGet(row, ["spare_parts_replaced", "Spare parts replaced"]));
  const orderReceiptRaw = _sbOrderText(_sbOrderGet(row, ["order_receipt", "Order Receipt", "delivery_receipt", "Delivery Receipt", "receipt_photos", "Receipt Photos"]));
  const maintenanceReceiptRaw = _sbOrderText(_sbOrderGet(row, ["maintenance_receipt", "Maintenance Receipt"]));
  const normalizeOrderReceiptEntries = (raw, fallbackPrefix = "Receipt") => {
    return _sbParseScreenshotEntries(raw)
      .map((entry, index) => {
        const url = _sbExtractUrl(entry?.url || entry?.href || entry?.publicUrl || entry?.name || "");
        const name = String(entry?.name || "").trim() || (url ? String(url).split(/[\/?#]/).filter(Boolean).pop() : `${fallbackPrefix} ${index + 1}`);
        return { name: name || `${fallbackPrefix} ${index + 1}`, url: url || "" };
      })
      .filter((entry) => entry.name || entry.url);
  };
  const orderReceiptEntries = normalizeOrderReceiptEntries(orderReceiptRaw, "Receipt photo");
  const maintenanceReceiptEntries = normalizeOrderReceiptEntries(maintenanceReceiptRaw || orderReceiptRaw, "Receipt photo");
  const orderReceiptNames = orderReceiptEntries.map((entry) => entry.name).filter(Boolean);
  const orderReceiptUrls = orderReceiptEntries.map((entry) => entry.url).filter(Boolean);
  const maintenanceReceiptNames = maintenanceReceiptEntries.map((entry) => entry.name).filter(Boolean);
  const maintenanceReceiptUrls = maintenanceReceiptEntries.map((entry) => entry.url).filter(Boolean);
  const productName =
    _sbOrderText(_sbOrderGet(row, ["product_name", "Product Name"])) ||
    _sbOrderText(_sbOrderGet(row, ["product", "Product"])) ||
    "Unknown Product";
  const createdTime =
    _sbOrderDate(_sbOrderGet(row, ["notion_created_time", "created_time", "created_at", "Created time"])) ||
    new Date().toISOString();

  return {
    id,
    orderId: Number.isFinite(orderNum) ? `ORD-${orderNum}` : (id ? `ORD-${id}` : null),
    orderIdPrefix: Number.isFinite(orderNum) ? "ORD" : null,
    orderIdNumber: Number.isFinite(orderNum) ? orderNum : null,
    reason: _sbOrderText(_sbOrderGet(row, ["reason", "Reason"])) || "No Reason",
    productName,
    productPageId: _sbOrderText(_sbOrderGet(row, ["product_url", "product", "Product"])) || null,
    productUrl: _sbOrderText(_sbOrderGet(row, ["product_url", "Product URL"])) || null,
    productImage: null,
    unitPrice: _sbOrderNum(_sbOrderGet(row, ["unit_price", "Unit price", "Unity Price", "Price"])),
    quantityRequested: qtyRequested !== null ? qtyRequested : qtyBase,
    quantityProgress: qtyEditedBySupervisor,
    quantityEditedBySupervisor: qtyEditedBySupervisor,
    quantityReceived: qtyReceived,
    quantityRemaining: qtyRemaining,
    quantityReceivedEdited,
    quantity: qtyBase,
    status,
    statusColor: _sbOrderStatusColor(status),
    orderType,
    orderTypeColor: _sbOrderTypeColor(orderType),
    issueDescription: _sbOrderText(_sbOrderGet(row, ["issue_description", "Issue Description"])) || null,
    actualIssueDescription: _sbOrderText(_sbOrderGet(row, ["actual_issue_description", "Actual Issue Description"])) || null,
    repairAction: _sbOrderText(_sbOrderGet(row, ["repair_action", "Repair Action"])) || null,
    resolutionMethod: _sbOrderText(_sbOrderGet(row, ["resolution_method", "Resolution Method"])) || null,
    resolutionMethodColor: null,
    sparePartsReplacedIds: [],
    sparePartsReplacedId: null,
    sparePartsReplacedNames: spareParts,
    sparePartsReplacedName: spareParts.join(", ") || null,
    orderReceiptEntries,
    orderReceiptNames,
    orderReceiptUrls,
    orderReceiptName: orderReceiptNames[0] || null,
    orderReceiptUrl: orderReceiptUrls[0] || null,
    maintenanceReceiptEntries,
    maintenanceReceiptNames,
    maintenanceReceiptUrls,
    maintenanceReceiptName: maintenanceReceiptNames[0] || null,
    maintenanceReceiptUrl: maintenanceReceiptUrls[0] || null,
    operationsByIds: [],
    operationsByNames: operationsByName ? [operationsByName] : [],
    operationsById: "",
    operationsByName,
    receiptNumber: _sbOrderText(_sbOrderGet(row, ["receipt_number", "Receipt Number", "Store Receipt Number"])) || null,
    createdTime,
    createdById: createdById || createdByName,
    createdByName,
    assignedToIds: [],
    assignedToNames: _sbOrderText(_sbOrderGet(row, ["supervisor", "Supervisor"])) ? [_sbOrderText(_sbOrderGet(row, ["supervisor", "Supervisor"]))] : [],
    assignedToId: "",
    assignedToName: _sbOrderText(_sbOrderGet(row, ["supervisor", "Supervisor"])) || "",
    svApproval: _sbOrderText(_sbOrderGet(row, ["sv_approval", "S.V Approval", "SV Approval"])) || null,
    source: "supabase",
  };
}

async function _sbSelectOrdersRows({ approvedOnly = false } = {}) {
  const rows = await supabaseDb.selectAll(_sbOrdersTable(), {
    limit: 5000,
    order: "notion_created_time.desc,id.desc",
  });
  const list = Array.isArray(rows) ? rows : [];
  if (!approvedOnly) return list;
  return list.filter((row) => norm(_sbOrderGet(row, ["sv_approval", "S.V Approval", "SV Approval"])) === "approved");
}

async function _sbRequestedOrdersList() {
  const rows = await _sbSelectOrdersRows({ approvedOnly: true });
  return rows.map(_sbSerializeOrderRow);
}

async function _sbCurrentOrdersList(req) {
  const rows = await _sbSelectOrdersRows({ approvedOnly: false });
  const username = norm(req?.session?.username || "");
  const filtered = username
    ? rows.filter((row) => {
        const by = norm(_sbOrderGet(row, ["team_member_name", "teams_members", "Teams Members", "supervisor", "Supervisor"]));
        return !by || by.includes(username) || username.includes(by);
      })
    : rows;
  return filtered.map(_sbSerializeOrderRow);
}

async function _sbUpdateOrdersByIds(orderIds = [], patch = {}) {
  const ids = (Array.isArray(orderIds) ? orderIds : [])
    .map((x) => String(x || "").trim())
    .filter(Boolean)
    .filter((x) => /^\d+$/.test(x));
  if (!ids.length) return [];
  return await Promise.all(ids.map((id) => supabaseDb.updateById(_sbOrdersTable(), id, patch)));
}


async function _sbUpdateOrdersByIdsWithQuantities(orderIds = [], basePatch = {}, quantities = null) {
  const ids = (Array.isArray(orderIds) ? orderIds : [])
    .map((x) => String(x || "").trim())
    .filter(Boolean)
    .filter((x) => /^\d+$/.test(x));
  if (!ids.length) return [];

  const explicitQuantities = quantities && typeof quantities === "object" ? quantities : null;
  const out = [];

  for (const id of ids) {
    const patch = { ...basePatch };
    const row = await supabaseDb.selectById(_sbOrdersTable(), id).catch(() => null);
    const serialized = row ? _sbSerializeOrderRow(row) : null;
    const base = serialized ? Number(serialized.quantity) || 0 : 0;

    const hasExplicit = explicitQuantities && Object.prototype.hasOwnProperty.call(explicitQuantities, id);
    const explicit = hasExplicit ? Number(explicitQuantities[id]) : null;

    if (hasExplicit && Number.isFinite(explicit)) {
      const rounded = clampOrderQtyToBase(base, roundOrderQty(explicit));
      patch.quantity_received_by_operations = rounded;
      patch.quantity_remaining = roundOrderQty(base - rounded);
    } else if (row) {
      // Match the old Notion workflow after moving to Supabase:
      // clicking "Received by operations" from Not Started should fill the full item quantity
      // for rows that have not been edited yet. Previously the Supabase branch only changed
      // status, leaving received=0/remaining=base or 0/0 placeholders, so orders appeared in
      // both Received and Remaining tabs incorrectly after refresh.
      const currentReceivedRaw = _sbOrderNum(_sbOrderGet(row, [
        "quantity_received_by_operations",
        "Quantity Received by operations",
        "Quantity Received by Operations",
        "received_quantity",
        "quantity_received",
      ]));
      const currentRemainingRaw = _sbOrderNum(_sbOrderGet(row, ["quantity_remaining", "Quantity Remaining", "remaining_quantity"]));
      const currentReceived = serialized.quantityReceived;
      const currentRemaining = serialized.quantityRemaining;
      const hasMeaningfulReceived = currentReceived !== null && Math.abs(Number(currentReceived) || 0) > 1e-9;
      const hasRemaining = Math.abs(Number(currentRemaining) || 0) > 1e-9;
      const rawLooksPlaceholder =
        currentReceivedRaw !== null &&
        Math.abs(Number(currentReceivedRaw) || 0) < 1e-9 &&
        (
          currentRemainingRaw === null ||
          Math.abs(Number(currentRemainingRaw) || 0) < 1e-9 ||
          Math.abs(roundOrderQty(Number(currentRemainingRaw) - base)) < 1e-9
        );

      if (!hasMeaningfulReceived || rawLooksPlaceholder) {
        const rounded = roundOrderQty(base);
        patch.quantity_received_by_operations = rounded;
        patch.quantity_remaining = 0;
      } else if (hasRemaining) {
        // Preserve a real partial quantity; just keep remaining synchronized.
        patch.quantity_received_by_operations = roundOrderQty(Number(currentReceived) || 0);
        patch.quantity_remaining = roundOrderQty(base - (Number(currentReceived) || 0));
      }
    }

    out.push(await supabaseDb.updateById(_sbOrdersTable(), id, patch));
  }
  return out;
}

async function _sbInvalidateOrdersCaches(req = null) {
  const keys = [
    "cache:api:orders:requested:supabase:v1",
    "cache:api:orders:current:supabase:v1",
    "cache:api:orders:current:supabase:v1:all",
  ];
  const username = String(req?.session?.username || "").trim();
  if (username) keys.push(`cache:api:orders:current:supabase:v1:${normKey(username)}`);
  await Promise.all(Array.from(new Set(keys)).map((key) => cacheDel(key)));
}


function _sbOrderFinalStatusName(status) {
  return /(arrived|delivered|received)/i.test(String(status || ""));
}

function _sbCleanInsertRow(row = {}) {
  const out = {};
  for (const [key, value] of Object.entries(row || {})) {
    if (!key) continue;
    if (typeof value === "undefined") continue;
    if (typeof value === "number" && !Number.isFinite(value)) {
      out[key] = null;
      continue;
    }
    out[key] = value;
  }
  return out;
}

function _sbEffectiveDeliveredQty(item = {}) {
  const received = Number(item.quantityReceived);
  if (item.quantityReceived !== null && typeof item.quantityReceived !== "undefined" && hasNonZeroOrderQty(received)) {
    return Math.abs(roundOrderQty(received));
  }

  const candidates = [item.quantityProgress, item.quantityRequested, item.quantity];
  for (const candidate of candidates) {
    const n = Number(candidate);
    if (Number.isFinite(n) && hasNonZeroOrderQty(n)) return Math.abs(roundOrderQty(n));
  }
  return 0;
}

async function _sbCreateRepeatOrderFromDeliveredRows(orderIds = [], {
  expectedSourceType,
  targetType,
  quantitySign = 1,
  defaultReason = "Request Products",
  successMessage = "Order created in Not Started.",
  noQuantityError = "No delivered quantities were found.",
  req = null,
} = {}) {
  const cleanIds = _sbOrderExportIds(orderIds);
  if (!cleanIds.length) {
    const err = new Error("orderIds required");
    err.status = 400;
    throw err;
  }

  const sourceRows = await _sbOrderRowsByIds(cleanIds);
  if (!sourceRows.length) {
    const err = new Error("Orders not found");
    err.status = 404;
    throw err;
  }

  const sourceItems = sourceRows.map(_sbSerializeOrderRow);
  const expectedKey = _normKeyOrderType(expectedSourceType);
  const wrongType = sourceItems.find((item) => _normKeyOrderType(item?.orderType) !== expectedKey);
  if (wrongType) {
    const err = new Error(`Only delivered ${expectedSourceType} orders can create this order.`);
    err.status = 400;
    throw err;
  }

  const notDelivered = sourceItems.find((item) => !_sbOrderFinalStatusName(item?.status));
  if (notDelivered) {
    const err = new Error("Order must be in Delivered / Arrived before creating this order.");
    err.status = 400;
    throw err;
  }

  const orderNumber = await _sbNextOrderNumber();
  const now = new Date().toISOString();
  const createdRows = [];
  const sign = Number(quantitySign) < 0 ? -1 : 1;
  const fallbackUserName = String(req?.session?.username || "").trim() || null;

  for (let index = 0; index < sourceRows.length; index += 1) {
    const sourceRow = sourceRows[index] || {};
    const item = sourceItems[index] || _sbSerializeOrderRow(sourceRow);
    const qtyAbs = _sbEffectiveDeliveredQty(item);
    if (!hasNonZeroOrderQty(qtyAbs)) continue;

    const qty = roundOrderQty(sign * qtyAbs);
    const teamMemberName =
      item.createdByName ||
      _sbOrderText(_sbOrderGet(sourceRow, ["team_member_name", "teams_members", "Teams Members", "Supervisor", "supervisor"])) ||
      fallbackUserName;
    const supervisorName =
      item.assignedToName ||
      _sbOrderText(_sbOrderGet(sourceRow, ["supervisor", "Supervisor"])) ||
      null;

    const row = _sbCleanInsertRow({
      reason: String(item.reason || defaultReason || "Request Products").trim() || defaultReason || null,
      order_number: orderNumber,
      order_type: _canonicalOrderTypeLabel(targetType) || targetType || null,
      notion_created_time: now,
      product_name: item.productName || _sbOrderText(_sbOrderGet(sourceRow, ["product_name", "Product Name", "product", "Product"])) || "Unknown Product",
      product_url: item.productUrl || _sbOrderText(_sbOrderGet(sourceRow, ["product_url", "Product URL"])) || null,
      unit_price: Number.isFinite(Number(item.unitPrice)) ? Number(item.unitPrice) : null,
      quantity_requested: qty,
      quantity_progress: qty,
      quantity_received_by_operations: 0,
      quantity_remaining: qty,
      status: "Under Supervision",
      sv_approval: "Approved",
      team_member_name: teamMemberName || null,
      issue_description: item.issueDescription || _sbOrderText(_sbOrderGet(sourceRow, ["issue_description", "Issue Description"])) || null,
      supervisor: supervisorName || null,
      person_received_by_operations: null,
      order_receipt: null,
      receipt_number: null,
      maintenance_receipt: null,
    });

    try {
      createdRows.push(await supabaseDb.insert(_sbOrdersTable(), row));
    } catch (firstErr) {
      // Some older Supabase imports may not have optional receipt columns. Retry with
      // the core order columns only so the Create Withdrawal action remains reliable.
      const fallbackRow = { ...row };
      delete fallbackRow.order_receipt;
      delete fallbackRow.receipt_number;
      delete fallbackRow.maintenance_receipt;
      createdRows.push(await supabaseDb.insert(_sbOrdersTable(), fallbackRow));
    }
  }

  if (!createdRows.length) {
    const err = new Error(noQuantityError);
    err.status = 400;
    throw err;
  }

  await _sbInvalidateOrdersCaches();

  return {
    success: true,
    source: "supabase",
    createdCount: createdRows.length,
    orderIdNumber: Number.isFinite(Number(orderNumber)) ? Number(orderNumber) : null,
    message: successMessage,
  };
}


function _sbOrderExportIds(ids = []) {
  return (Array.isArray(ids) ? ids : [])
    .map((x) => String(x || "").trim())
    .filter(Boolean)
    .filter((x) => /^\d+$/.test(x));
}

async function _sbOrderRowsByIds(ids = []) {
  const cleanIds = _sbOrderExportIds(ids);
  if (!cleanIds.length) return [];
  const rows = await Promise.all(
    cleanIds.map((id) => supabaseDb.selectById(_sbOrdersTable(), id).catch(() => null)),
  );
  const byId = new Map(rows.filter(Boolean).map((row) => [String(row.id), row]));
  return cleanIds.map((id) => byId.get(String(id))).filter(Boolean);
}

function _sbComputeOrderIdRangeFromItems(items = []) {
  const nums = (items || [])
    .map((item) => Number(item?.orderIdNumber))
    .filter((n) => Number.isFinite(n));
  if (nums.length) {
    const min = Math.min(...nums);
    const max = Math.max(...nums);
    if (min === max) return `ORD-${min}`;
    return `ORD-${min} : ORD-${max}`;
  }
  const ids = (items || []).map((item) => item?.orderId).filter(Boolean);
  if (!ids.length) return "Order";
  if (ids.length === 1) return ids[0];
  return `${ids[0]} : ${ids[ids.length - 1]}`;
}

async function _sbProductsMapByName() {
  if (!_sbProductsEnabled()) return new Map();
  const products = await _sbProductsList().catch(() => []);
  const map = new Map();
  for (const p of products || []) {
    const key = normKey(p?.name || "");
    if (key && !map.has(key)) map.set(key, p);
  }
  return map;
}

async function _sbBuildOrderExportPayload(orderIds = [], req = null) {
  const rowsRaw = await _sbOrderRowsByIds(orderIds);
  if (!rowsRaw.length) {
    const err = new Error("Orders not found");
    err.status = 404;
    throw err;
  }

  const items = rowsRaw.map(_sbSerializeOrderRow);
  const productNameMap = await _sbProductsMapByName();
  const createdTimes = items
    .map((item) => new Date(item.createdTime || Date.now()))
    .filter((d) => !Number.isNaN(d.getTime()));
  const createdAt = createdTimes.length
    ? new Date(Math.min(...createdTimes.map((d) => d.getTime())))
    : new Date();

  const orderIdRange = _sbComputeOrderIdRangeFromItems(items);
  const first = items[0] || {};
  const teamMember = first.createdByName || first.assignedToName || "";
  const operationsBy = first.operationsByName || req?.session?.username || "";
  const receiptView = _receiptPresentationForOrderType(first.orderType || "Request Products");

  const rows = [];
  let grandQty = 0;
  let grandTotal = 0;
  for (const item of items) {
    const prod = productNameMap.get(normKey(item.productName || "")) || null;
    const qtyCandidate = item.quantityReceived !== null && typeof item.quantityReceived !== "undefined"
      ? item.quantityReceived
      : (item.quantityProgress !== null && typeof item.quantityProgress !== "undefined" ? item.quantityProgress : item.quantity);
    const qty = Number.isFinite(Number(qtyCandidate)) ? Number(qtyCandidate) : 0;
    const unitCandidate = item.unitPrice !== null && typeof item.unitPrice !== "undefined" ? item.unitPrice : prod?.unitPrice;
    const unit = Number.isFinite(Number(unitCandidate)) ? Number(unitCandidate) : 0;
    const total = qty * unit;
    grandQty += qty;
    grandTotal += total;
    rows.push({
      idCode: prod?.displayId || "",
      component: item.productName || prod?.name || "Unknown Product",
      qty,
      reason: item.reason || "No Reason",
      link: item.productUrl || prod?.url || "",
      unit,
      total,
    });
  }

  const reasonCounts = new Map();
  for (const row of rows) {
    const key = String(row?.reason || "").trim() || "No Reason";
    reasonCounts.set(key, (reasonCounts.get(key) || 0) + 1);
  }
  const groupReason = Array.from(reasonCounts.entries()).sort((a, b) => b[1] - a[1])[0]?.[0] || "No Reason";

  return {
    rawRows: rowsRaw,
    items,
    rows,
    grandQty,
    grandTotal,
    createdAt,
    orderIdRange,
    teamMember,
    operationsBy,
    groupReason,
    receiptView,
    first,
  };
}

function _sbSafeExportName(value = "order") {
  return String(value || "order")
    .replace(/[\\/:*?"<>|]/g, "-")
    .replace(/\s+/g, "_")
    .slice(0, 60);
}

async function _sbPipeOrderDeliveryPdf(req, res, orderIds = [], { tab = "" } = {}) {
  const tabKey = String(tab || "").trim().toLowerCase();
  const hideCosts = tabKey === "received" || tabKey === "delivered";
  const payload = await _sbBuildOrderExportPayload(orderIds, req);
  const fileName = `${payload.receiptView.filePrefix}_${_sbSafeExportName(payload.orderIdRange)}.pdf`;
  res.setHeader("Content-Type", "application/pdf");
  res.setHeader("Content-Disposition", `attachment; filename="${fileName}"; filename*=UTF-8''${encodeURIComponent(fileName)}`);
  res.setHeader("Cache-Control", "no-store");
  const { pipeDeliveryReceiptPDF } = require("./deliveryReceiptPdf");
  await pipeDeliveryReceiptPDF({
    orderId: payload.orderIdRange,
    createdAt: payload.createdAt,
    teamMember: payload.teamMember,
    preparedBy: payload.groupReason,
    rows: payload.rows,
    grandQty: payload.grandQty,
    grandTotal: payload.grandTotal,
    metaLayout: "teamReasonFirst",
    showReasonTagBar: false,
    groupByReason: false,
    headerColorKey: payload.groupReason,
    showCosts: !hideCosts,
    documentTitle: payload.receiptView.documentTitle,
    recipientLabelLeft: payload.receiptView.recipientLabelLeft,
    thirdSignatureLabel: payload.receiptView.thirdSignatureLabel,
  }, res);
}

async function _sbPipeOrderMaintenancePdf(req, res, orderIds = []) {
  const payload = await _sbBuildOrderExportPayload(orderIds, req);
  const first = payload.first || {};
  if (_normKeyOrderType(first.orderType || "") !== _normKeyOrderType("Request Maintenance")) {
    return res.status(400).json({ error: "This export is only available for maintenance orders." });
  }
  const fileName = `maintenance_receipt_${_sbSafeExportName(payload.orderIdRange)}.pdf`;
  res.setHeader("Content-Type", "application/pdf");
  res.setHeader("Content-Disposition", `attachment; filename="${fileName}"; filename*=UTF-8''${encodeURIComponent(fileName)}`);
  res.setHeader("Cache-Control", "no-store");
  const { pipeMaintenanceReceiptPDF } = require("./maintenanceReceiptPdf");
  await pipeMaintenanceReceiptPDF({
    orderId: payload.orderIdRange,
    createdAt: payload.createdAt,
    requestedBy: payload.teamMember,
    operationsBy: payload.operationsBy,
    issueDescription: first.issueDescription || "—",
    actualIssueDescription: first.actualIssueDescription || "—",
    repairAction: first.repairAction || "—",
    resolutionMethod: first.resolutionMethod || "—",
    sparePartsReplacedList: first.sparePartsReplacedNames || [],
    rows: payload.rows,
    maintenanceReceiptName: first.maintenanceReceiptName || "",
    maintenanceReceiptUrl: first.maintenanceReceiptUrl || "",
  }, res);
}

async function _sbPipeOrderExcel(req, res, orderIds = []) {
  const ExcelJS = require("exceljs");
  const payload = await _sbBuildOrderExportPayload(orderIds, req);
  const wb = new ExcelJS.Workbook();
  wb.creator = "Operations Hub";
  wb.created = new Date();
  const ws = wb.addWorksheet("Order");

  const formatDateTime = (date) => {
    try {
      const d = date instanceof Date ? date : new Date(date);
      if (Number.isNaN(d.getTime())) return String(date || "-");
      return d.toLocaleString("en-GB", {
        day: "2-digit",
        month: "short",
        year: "numeric",
        hour: "2-digit",
        minute: "2-digit",
      });
    } catch {
      return String(date || "-");
    }
  };

  const borderThin = {
    top: { style: "thin", color: { argb: "FF000000" } },
    left: { style: "thin", color: { argb: "FF000000" } },
    bottom: { style: "thin", color: { argb: "FF000000" } },
    right: { style: "thin", color: { argb: "FF000000" } },
  };
  const borderLight = {
    top: { style: "thin", color: { argb: "FFE5E7EB" } },
    left: { style: "thin", color: { argb: "FFE5E7EB" } },
    bottom: { style: "thin", color: { argb: "FFE5E7EB" } },
    right: { style: "thin", color: { argb: "FFE5E7EB" } },
  };

  ws.addRow(["Order ID", payload.orderIdRange, "Date", formatDateTime(payload.createdAt)]);
  ws.addRow(["Team member", payload.teamMember || "", "Prepared by (Operations)", String(req.session?.username || "—")]);
  ws.addRow(["Total quantity", Number(payload.grandQty) || 0, "Estimate total", Number(payload.grandTotal) || 0]);
  for (let r = 1; r <= 3; r += 1) {
    const row = ws.getRow(r);
    row.height = 20;
    for (let c = 1; c <= 4; c += 1) {
      const cell = row.getCell(c);
      cell.border = borderThin;
      cell.alignment = { vertical: "middle", horizontal: "left", wrapText: true };
      if (c === 1 || c === 3) {
        cell.font = { bold: true };
        cell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FFEFEFEF" } };
      } else {
        cell.font = { bold: true };
      }
    }
  }
  ws.getRow(3).getCell(2).numFmt = "0";
  ws.getRow(3).getCell(4).numFmt = '"£"#,##0.00';
  ws.addRow([]);

  const reasonMap = new Map();
  for (const row of payload.rows || []) {
    const reason = String(row.reason || "").trim() || "No Reason";
    if (!reasonMap.has(reason)) reasonMap.set(reason, []);
    reasonMap.get(reason).push(row);
  }
  const reasons = Array.from(reasonMap.keys()).sort((a, b) => String(a).localeCompare(String(b)));
  const headerCols = ["ID Code", "Component", "Quantity", "Reason", "Component link", "Unit cost", "Total cost"];

  for (const reason of reasons) {
    const titleRow = ws.addRow([`Reason: ${reason} (${(reasonMap.get(reason) || []).length} items)`]);
    const titleNum = titleRow.number;
    ws.mergeCells(`A${titleNum}:G${titleNum}`);
    for (let c = 1; c <= 7; c += 1) {
      const cell = ws.getRow(titleNum).getCell(c);
      cell.border = borderThin;
      cell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FFF5F3FF" } };
      cell.font = { bold: true, color: { argb: "FF5B21B6" } };
    }
    const header = ws.addRow(headerCols);
    header.font = { bold: true, color: { argb: "FF111827" } };
    header.eachCell((cell) => {
      cell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: "FFEDE9FE" } };
      cell.border = borderThin;
      cell.alignment = { vertical: "middle", wrapText: true };
    });
    const items = (reasonMap.get(reason) || []).slice().sort((a, b) => String(a.component || "").localeCompare(String(b.component || "")));
    for (const item of items) {
      const r = ws.addRow([
        item.idCode || "",
        item.component || "",
        Number(item.qty) || 0,
        item.reason || "",
        item.link || "",
        Number(item.unit) || 0,
        Number(item.total) || 0,
      ]);
      if (item.link) {
        r.getCell(5).value = { text: item.link, hyperlink: item.link };
        r.getCell(5).font = { color: { argb: "FF2563EB" }, underline: true };
      }
      r.getCell(3).numFmt = "0.######";
      r.getCell(6).numFmt = '"£"#,##0.00';
      r.getCell(7).numFmt = '"£"#,##0.00';
      r.eachCell((cell) => {
        cell.border = borderLight;
        cell.alignment = { vertical: "middle", wrapText: true };
      });
    }
    ws.addRow([]);
  }

  ws.columns = [
    { width: 14 },
    { width: 36 },
    { width: 12 },
    { width: 24 },
    { width: 54 },
    { width: 14 },
    { width: 14 },
  ];
  ws.views = [{ state: "frozen", ySplit: 4 }];
  const fileName = `order_${_sbSafeExportName(payload.orderIdRange)}.xlsx`;
  const buf = await wb.xlsx.writeBuffer();
  res.setHeader("Content-Type", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
  res.setHeader("Content-Disposition", `attachment; filename="${fileName}"; filename*=UTF-8''${encodeURIComponent(fileName)}`);
  res.setHeader("Cache-Control", "no-store");
  res.send(Buffer.from(buf));
}


// -----------------------------------------------------------------------------
// Supabase Products adapter
// -----------------------------------------------------------------------------
function _sbProductsEnabled() {
  return !!(supabaseDb && supabaseDb.isConfigured && supabaseDb.isConfigured());
}

function _sbProductsTable() {
  return (supabaseDb.getConfig().productsTable || process.env.SUPABASE_PRODUCTS_TABLE || "products").trim() || "products";
}

function _sbProductTagsTable() {
  return String(process.env.SUPABASE_PRODUCT_TAGS_TABLE || process.env.SUPABASE_PRODUCTS_TAGS_TABLE || "product_tags").trim() || "product_tags";
}

function _sbIsMissingTableError(error) {
  const text = [error?.message, error?.details?.message, error?.details?.details, error?.details?.hint, error?.details?.code]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();
  return error?.status === 404 || text.includes("could not find the table") || text.includes("schema cache") || text.includes("does not exist");
}

function _sbProductNum(value) {
  if (value === null || typeof value === "undefined") return null;
  if (typeof value === "number") return Number.isFinite(value) ? value : null;
  const raw = String(value || "").trim();
  if (!raw || /^null$/i.test(raw)) return null;
  const n = Number(raw.replace(/[^0-9.-]/g, ""));
  return Number.isFinite(n) ? n : null;
}

function _sbProductText(value) {
  const t = _sbString(value);
  return t && !/^null$/i.test(t) ? t : "";
}

function _sbProductGet(row, aliases = []) {
  return _sbGet(row, aliases);
}

function _sbProductTags(row = {}) {
  const tags = [];
  const push = (v) => {
    const t = _sbProductText(v).trim();
    if (t && !tags.some((x) => normKey(x) === normKey(t))) tags.push(t);
  };
  push(_sbProductGet(row, ["tags", "Tags", "tag", "Tag"]));
  return tags;
}

function _sbSerializeProductRow(row = {}) {
  const id = String(_sbProductGet(row, ["id", "ID"]) ?? "").trim();
  const name = _sbProductText(_sbProductGet(row, ["name", "Name", "product_name", "Product Name", "product", "Product"])) || "Untitled Product";
  const displayId = _sbProductText(_sbProductGet(row, ["id_code", "ID Code", "id code", "code", "Code"])) || null;
  const unitPrice = _sbProductNum(_sbProductGet(row, ["unit_price", "Unity Price", "Unit price", "Unit Price", "price", "Price"]));
  const url = _sbExtractUrl(_sbProductGet(row, ["url", "URL", "product_url", "Product URL", "link", "Link", "website", "Website"]));
  const imageUrl = _sbExtractUrl(_sbProductGet(row, ["image_url", "Image URL", "image", "Image", "photo", "Photo", "picture", "Picture", "thumbnail", "Thumbnail"]));
  return {
    id,
    name,
    url: url || null,
    unitPrice: unitPrice !== null ? unitPrice : null,
    displayId,
    imageUrl: imageUrl || null,
    tags: _sbProductTags(row),
    source: "supabase",
  };
}

async function _sbSelectProductsRows() {
  const rows = await supabaseDb.selectAll(_sbProductsTable(), {
    limit: 5000,
    order: "name.asc,id.asc",
  });
  return Array.isArray(rows) ? rows : [];
}

async function _sbProductsList() {
  const rows = await _sbSelectProductsRows();
  return rows.map(_sbSerializeProductRow).filter((p) => p && p.id && p.name);
}

async function _sbProductTagsTableList({ required = false } = {}) {
  try {
    const rows = await supabaseDb.selectAll(_sbProductTagsTable(), {
      limit: 1000,
      order: "name.asc",
    });
    return (Array.isArray(rows) ? rows : [])
      .map((row) => _sbProductText(_sbGet(row, ["name", "tag", "tags", "Name", "Tag"])) .trim())
      .filter(Boolean);
  } catch (error) {
    if (!required && _sbIsMissingTableError(error)) return [];
    if (required && _sbIsMissingTableError(error)) {
      const err = new Error("Product tags table is not created yet. Please run products_tags_catalog_migration.sql in Supabase first.");
      err.status = 400;
      throw err;
    }
    throw error;
  }
}

async function _sbProductsTagCatalogList() {
  const map = new Map();
  const add = (value) => {
    const tag = _sbProductText(value).trim();
    if (tag && !map.has(normKey(tag))) map.set(normKey(tag), tag);
  };

  for (const tag of await _sbProductTagsTableList({ required: false })) add(tag);
  for (const product of await _sbProductsList()) add(firstProductTagForServer(product));

  return Array.from(map.values()).sort((a, b) => String(a).localeCompare(String(b)));
}

async function _sbCreateProductTag(name) {
  const clean = _sbProductText(name).trim();
  if (!clean) {
    const err = new Error("Tag name is required.");
    err.status = 400;
    throw err;
  }

  const existing = await _sbProductsTagCatalogList();
  if (existing.some((tag) => normKey(tag) === normKey(clean))) {
    return { name: existing.find((tag) => normKey(tag) === normKey(clean)) || clean, alreadyExists: true };
  }

  const row = {
    name: clean,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };
  const created = await supabaseDb.insert(_sbProductTagsTable(), row).catch((error) => {
    if (_sbIsMissingTableError(error)) {
      const err = new Error("Product tags table is not created yet. Please run products_tags_catalog_migration.sql in Supabase first.");
      err.status = 400;
      throw err;
    }
    throw error;
  });
  await _sbInvalidateProductsCaches();
  return { name: _sbProductText(_sbGet(created || row, ["name", "tag", "Name", "Tag"])) || clean, alreadyExists: false };
}

function _sbProductNullableText(value) {
  const text = _sbProductText(value).trim();
  return text ? text : null;
}

function _sbProductNullableNum(value) {
  const n = _sbProductNum(value);
  return n === null ? null : n;
}

function _sbProductCleanUrl(value) {
  const raw = String(value || "").trim();
  if (!raw) return null;
  if (/^https?:\/\//i.test(raw)) return raw;
  return `https://${raw.replace(/^\/+/, "")}`;
}

function _sbNormalizeProductPayload(body = {}, { partial = false } = {}) {
  const out = {};
  const has = (key) => Object.prototype.hasOwnProperty.call(body || {}, key);

  const setText = (target, keys) => {
    for (const key of keys) {
      if (!has(key)) continue;
      out[target] = _sbProductNullableText(body[key]);
      return;
    }
  };
  const setNum = (target, keys) => {
    for (const key of keys) {
      if (!has(key)) continue;
      out[target] = _sbProductNullableNum(body[key]);
      return;
    }
  };

  setText("name", ["name", "productName", "product_name"]);
  setText("id_code", ["idCode", "id_code", "code"]);
  setText("tags", ["tags", "tag"]);
  setNum("unit_price", ["unitPrice", "unit_price", "price"]);

  if (has("url") || has("productUrl") || has("product_url") || has("link")) {
    out.url = _sbProductCleanUrl(body.url ?? body.productUrl ?? body.product_url ?? body.link);
  }

  if (!partial && !String(out.name || "").trim()) {
    const err = new Error("Product name is required.");
    err.status = 400;
    throw err;
  }

  if (Object.prototype.hasOwnProperty.call(out, "name") && !String(out.name || "").trim()) {
    const err = new Error("Product name is required.");
    err.status = 400;
    throw err;
  }

  out.updated_at = new Date().toISOString();
  return out;
}

async function _sbProductById(productId) {
  const id = String(productId || "").trim();
  if (!id) return null;
  const row = await supabaseDb.selectById(_sbProductsTable(), id);
  return row ? _sbSerializeProductRow(row) : null;
}

async function _sbCreateProduct(body = {}) {
  const row = _sbNormalizeProductPayload(body, { partial: false });
  const created = await supabaseDb.insert(_sbProductsTable(), row);
  await _sbInvalidateProductsCaches();
  return _sbSerializeProductRow(created || row);
}

async function _sbUpdateProduct(productId, body = {}) {
  const id = String(productId || "").trim();
  if (!id) {
    const err = new Error("Missing product ID.");
    err.status = 400;
    throw err;
  }
  const row = _sbNormalizeProductPayload(body, { partial: true });
  const updated = await supabaseDb.updateById(_sbProductsTable(), id, row);
  await _sbInvalidateProductsCaches();
  return _sbSerializeProductRow(updated || { ...row, id });
}

function _sbProductChunk(list = [], size = 100) {
  const out = [];
  const cleanSize = Math.max(1, Number(size) || 100);
  for (let i = 0; i < list.length; i += cleanSize) out.push(list.slice(i, i + cleanSize));
  return out;
}

async function _sbUpdateProductsTag(oldTag, newTag) {
  const fromTag = _sbProductText(oldTag).trim();
  const toTag = _sbProductText(newTag).trim();

  if (!fromTag) {
    const err = new Error("Current tag is required.");
    err.status = 400;
    throw err;
  }
  if (!toTag) {
    const err = new Error("New tag is required.");
    err.status = 400;
    throw err;
  }
  if (normKey(fromTag) === normKey(toTag)) {
    const err = new Error("Please enter a different tag name.");
    err.status = 400;
    throw err;
  }

  const products = await _sbProductsList();
  const matches = products.filter((product) => firstProductTagForServer(product) === fromTag);
  if (!matches.length) {
    const err = new Error("No products were found under this tag.");
    err.status = 404;
    throw err;
  }

  const row = {
    tags: toTag,
    updated_at: new Date().toISOString(),
  };

  const updatedRows = [];
  for (const ids of _sbProductChunk(matches.map((product) => product.id), 120)) {
    const batch = await supabaseDb.updateByIds(_sbProductsTable(), ids, row);
    if (Array.isArray(batch)) updatedRows.push(...batch);
  }

  await _sbInvalidateProductsCaches();

  return {
    oldTag: fromTag,
    newTag: toTag,
    updatedCount: matches.length,
    products: updatedRows.map(_sbSerializeProductRow).filter((product) => product && product.id),
  };
}

function firstProductTagForServer(product) {
  const tags = Array.isArray(product?.tags) ? product.tags : [];
  const first = tags.map((x) => String(x || "").trim()).find(Boolean);
  return first || "Uncategorized";
}


function _sbProductProposalsTable() {
  return String(process.env.SUPABASE_PRODUCT_PROPOSALS_TABLE || "product_proposals").trim() || "product_proposals";
}

function _sbProductProposalItemsTable() {
  return String(process.env.SUPABASE_PRODUCT_PROPOSAL_ITEMS_TABLE || "product_proposal_items").trim() || "product_proposal_items";
}

function _sbProposalText(value) {
  return _sbProductText(value).trim();
}

function _sbProposalQuantity(value) {
  const n = Number(value);
  if (!Number.isFinite(n) || n <= 0) return 1;
  return Math.max(1, Math.round(n));
}

function _sbProposalMissingTableError(error) {
  if (_sbIsMissingTableError(error)) {
    const err = new Error("Products proposals tables are not created yet. Please run products_proposals_migration.sql in Supabase first.");
    err.status = 400;
    return err;
  }
  return error;
}

function _sbProposalOwnerInfo(row = {}) {
  return {
    createdBy: _sbProposalText(_sbGet(row, ["created_by", "createdBy", "Created By"])) || null,
    createdById: _sbProposalText(_sbGet(row, ["created_by_id", "createdById", "Created By ID"])) || null,
  };
}

function _sbProposalCurrentUserOwns(row = {}, req = null) {
  const owner = _sbProposalOwnerInfo(row);
  const sessionId = String(req?.session?.userSupabaseId || "").trim();
  const sessionName = String(req?.session?.username || "").trim();
  if (owner.createdById && sessionId && String(owner.createdById) === sessionId) return true;
  if (owner.createdBy && sessionName && norm(owner.createdBy) === norm(sessionName)) return true;
  return false;
}

async function _sbAssertProposalOwnerOrAdmin(row = {}, req = null, body = {}) {
  if (_sbProposalCurrentUserOwns(row, req)) return true;
  const adminPassword = String(body?.adminPassword || body?.admin_password || req?.query?.adminPassword || "").trim();
  if (adminPassword && await verifyAdminPassword(adminPassword)) return true;
  const err = new Error("Admin password is required to modify a folder created by another user.");
  err.status = 403;
  throw err;
}

function _sbSerializeProductProposal(row = {}, itemsCount = 0, req = null) {
  const id = String(_sbGet(row, ["id", "ID"]) ?? "").trim();
  const name = _sbProposalText(_sbGet(row, ["name", "Name", "proposal_name", "Proposal Name"])) || "Untitled Proposal";
  const owner = _sbProposalOwnerInfo(row);
  return {
    id,
    name,
    createdBy: owner.createdBy,
    createdById: owner.createdById,
    createdAt: _sbProposalText(_sbGet(row, ["created_at", "createdAt", "Created At"])) || null,
    updatedAt: _sbProposalText(_sbGet(row, ["updated_at", "updatedAt", "Updated At"])) || null,
    itemsCount: Number(itemsCount) || 0,
    canEdit: req ? _sbProposalCurrentUserOwns(row, req) : false,
  };
}

function _sbSerializeProductProposalItem(row = {}) {
  const id = String(_sbGet(row, ["id", "ID"]) ?? "").trim();
  return {
    id,
    proposalId: String(_sbGet(row, ["proposal_id", "proposalId", "Proposal ID"]) ?? "").trim(),
    productId: String(_sbGet(row, ["product_id", "productId", "Product ID"]) ?? "").trim() || null,
    productName: _sbProposalText(_sbGet(row, ["product_name", "productName", "Product Name", "name", "Name"])) || "Untitled Product",
    quantity: _sbProposalQuantity(_sbGet(row, ["quantity", "qty", "Quantity", "Qty"])),
    createdAt: _sbProposalText(_sbGet(row, ["created_at", "createdAt", "Created At"])) || null,
    updatedAt: _sbProposalText(_sbGet(row, ["updated_at", "updatedAt", "Updated At"])) || null,
  };
}

async function _sbProposalRows() {
  try {
    return await supabaseDb.selectAll(_sbProductProposalsTable(), { limit: 1000, order: "updated_at.desc,created_at.desc" });
  } catch (error) {
    throw _sbProposalMissingTableError(error);
  }
}

async function _sbProposalItemRows(proposalId = null) {
  try {
    if (proposalId) {
      const table = encodeURIComponent(_sbProductProposalItemsTable());
      const id = encodeURIComponent(String(proposalId || "").trim());
      const rows = await supabaseDb.request(`/${table}?select=*&proposal_id=eq.${id}&order=created_at.asc`);
      return Array.isArray(rows) ? rows : [];
    }
    return await supabaseDb.selectAll(_sbProductProposalItemsTable(), { limit: 5000, order: "created_at.asc" });
  } catch (error) {
    throw _sbProposalMissingTableError(error);
  }
}

async function _sbProductsProposalsList(req = null) {
  const [proposals, items] = await Promise.all([_sbProposalRows(), _sbProposalItemRows(null)]);
  const counts = new Map();
  for (const item of items || []) {
    const pid = String(_sbGet(item, ["proposal_id", "proposalId", "Proposal ID"]) ?? "").trim();
    if (pid) counts.set(pid, (counts.get(pid) || 0) + 1);
  }
  return (proposals || []).map((row) => _sbSerializeProductProposal(row, counts.get(String(_sbGet(row, ["id", "ID"]) ?? "").trim()) || 0, req));
}

async function _sbProductProposalById(proposalId, req = null) {
  const id = String(proposalId || "").trim();
  if (!id) return null;
  try {
    const row = await supabaseDb.selectById(_sbProductProposalsTable(), id);
    if (!row) return null;
    const items = (await _sbProposalItemRows(id)).map(_sbSerializeProductProposalItem).filter((item) => item.id);
    return { proposal: _sbSerializeProductProposal(row, items.length, req), items };
  } catch (error) {
    throw _sbProposalMissingTableError(error);
  }
}

async function _sbTouchProductProposal(proposalId) {
  try {
    await supabaseDb.updateById(_sbProductProposalsTable(), proposalId, { updated_at: new Date().toISOString() });
  } catch (error) {
    if (!_sbIsMissingTableError(error)) throw error;
  }
}

async function _sbCreateProductProposal(body = {}, req = null) {
  const name = _sbProposalText(body?.name || body?.proposalName || body?.title);
  if (!name) {
    const err = new Error("Proposal name is required.");
    err.status = 400;
    throw err;
  }
  const now = new Date().toISOString();
  const row = {
    name,
    created_by: String(req?.session?.username || "").trim() || null,
    created_by_id: String(req?.session?.userSupabaseId || "").trim() || null,
    created_at: now,
    updated_at: now,
  };
  try {
    const created = await supabaseDb.insert(_sbProductProposalsTable(), row);
    return _sbSerializeProductProposal(created || row, 0);
  } catch (error) {
    throw _sbProposalMissingTableError(error);
  }
}

async function _sbUpdateProductProposal(proposalId, body = {}, req = null) {
  const id = String(proposalId || "").trim();
  const name = _sbProposalText(body?.name || body?.proposalName || body?.title);
  if (!id || !name) {
    const err = new Error("Proposal name is required.");
    err.status = 400;
    throw err;
  }
  const row = await supabaseDb.selectById(_sbProductProposalsTable(), id);
  if (!row) {
    const err = new Error("Proposal not found.");
    err.status = 404;
    throw err;
  }
  await _sbAssertProposalOwnerOrAdmin(row, req, body);
  await supabaseDb.updateById(_sbProductProposalsTable(), id, { name, updated_at: new Date().toISOString() });
  return (await _sbProductProposalById(id, req)).proposal;
}

async function _sbDeleteProductProposal(proposalId, body = {}, req = null) {
  const id = String(proposalId || "").trim();
  if (!id) {
    const err = new Error("Proposal ID is required.");
    err.status = 400;
    throw err;
  }
  const row = await supabaseDb.selectById(_sbProductProposalsTable(), id);
  if (!row) {
    const err = new Error("Proposal not found.");
    err.status = 404;
    throw err;
  }
  await _sbAssertProposalOwnerOrAdmin(row, req, body);
  const items = await _sbProposalItemRows(id);
  for (const item of items || []) {
    const itemId = String(_sbGet(item, ["id", "ID"]) ?? "").trim();
    if (itemId) await supabaseDb.deleteById(_sbProductProposalItemsTable(), itemId);
  }
  await supabaseDb.deleteById(_sbProductProposalsTable(), id);
  return { deleted: true, id };
}


async function _sbCopyProductProposal(proposalId, body = {}, req = null) {
  const sourceId = String(proposalId || "").trim();
  const name = _sbProposalText(body?.name || body?.proposalName || body?.title);
  if (!sourceId || !name) {
    const err = new Error("Copy name is required.");
    err.status = 400;
    throw err;
  }
  const source = await supabaseDb.selectById(_sbProductProposalsTable(), sourceId);
  if (!source) {
    const err = new Error("Proposal not found.");
    err.status = 404;
    throw err;
  }
  const now = new Date().toISOString();
  const created = await supabaseDb.insert(_sbProductProposalsTable(), {
    name,
    created_by: String(req?.session?.username || "").trim() || null,
    created_by_id: String(req?.session?.userSupabaseId || "").trim() || null,
    created_at: now,
    updated_at: now,
  });
  const newId = String(_sbGet(created, ["id", "ID"]) ?? "").trim();
  if (!newId) return _sbSerializeProductProposal(created || { name }, 0, req);
  const items = await _sbProposalItemRows(sourceId);
  const productMap = await _sbProductsMapById();
  for (const item of items || []) {
    const productId = String(_sbGet(item, ["product_id", "productId", "Product ID"]) ?? "").trim();
    const product = productMap.get(productId) || { id: productId, name: _sbProposalText(_sbGet(item, ["product_name", "Product Name", "name", "Name"])) };
    if (!product?.id) continue;
    await _sbUpsertProductProposalItem(newId, product, _sbProposalQuantity(_sbGet(item, ["quantity", "qty", "Quantity", "Qty"])));
  }
  return (await _sbProductProposalById(newId, req)).proposal;
}

async function _sbRequireEditableProductProposal(proposalId, req = null, body = {}) {
  const row = await supabaseDb.selectById(_sbProductProposalsTable(), String(proposalId || "").trim());
  if (!row) {
    const err = new Error("Proposal not found.");
    err.status = 404;
    throw err;
  }
  await _sbAssertProposalOwnerOrAdmin(row, req, body);
  return row;
}

async function _sbUpsertProductProposalItem(proposalId, product, quantity) {
  const id = String(proposalId || "").trim();
  const productId = String(product?.id || "").trim();
  if (!id) {
    const err = new Error("Proposal ID is required.");
    err.status = 400;
    throw err;
  }
  if (!productId) {
    const err = new Error("Product is required.");
    err.status = 400;
    throw err;
  }
  const qty = _sbProposalQuantity(quantity);
  const now = new Date().toISOString();
  const existing = (await _sbProposalItemRows(id)).find((item) => String(_sbGet(item, ["product_id", "productId", "Product ID"]) ?? "").trim() === productId);
  if (existing) {
    const existingQty = _sbProposalQuantity(_sbGet(existing, ["quantity", "qty", "Quantity", "Qty"]));
    const updated = await supabaseDb.updateById(_sbProductProposalItemsTable(), String(_sbGet(existing, ["id", "ID"])), {
      quantity: existingQty + qty,
      product_name: product.name || "Untitled Product",
      updated_at: now,
    });
    return _sbSerializeProductProposalItem(updated || existing);
  }
  const row = {
    proposal_id: id,
    product_id: productId,
    product_name: product.name || "Untitled Product",
    quantity: qty,
    created_at: now,
    updated_at: now,
  };
  const created = await supabaseDb.insert(_sbProductProposalItemsTable(), row);
  return _sbSerializeProductProposalItem(created || row);
}

async function _sbAddProductProposalItem(proposalId, body = {}, req = null) {
  const productId = String(body?.productId || body?.product_id || body?.id || "").trim();
  const product = await _sbProductById(productId);
  if (!product) {
    const err = new Error("Product not found.");
    err.status = 404;
    throw err;
  }
  await _sbRequireEditableProductProposal(proposalId, req, body);
  await _sbUpsertProductProposalItem(proposalId, product, body?.quantity || body?.qty || 1);
  await _sbTouchProductProposal(proposalId);
  return await _sbProductProposalById(proposalId, req);
}

async function _sbAddProductProposalItemsByTag(proposalId, body = {}, req = null) {
  const tag = _sbProposalText(body?.tag || body?.tags || body?.name);
  if (!tag) {
    const err = new Error("Tag is required.");
    err.status = 400;
    throw err;
  }
  await _sbRequireEditableProductProposal(proposalId, req, body);
  const products = (await _sbProductsList()).filter((product) => firstProductTagForServer(product) === tag);
  if (!products.length) {
    const err = new Error("No products were found under this tag.");
    err.status = 404;
    throw err;
  }
  for (const product of products) {
    await _sbUpsertProductProposalItem(proposalId, product, body?.quantity || body?.qty || 1);
  }
  await _sbTouchProductProposal(proposalId);
  const detail = await _sbProductProposalById(proposalId, req);
  return { ...detail, addedCount: products.length };
}

async function _sbUpdateProductProposalItem(proposalId, itemId, body = {}, req = null) {
  const pid = String(proposalId || "").trim();
  const iid = String(itemId || "").trim();
  if (!pid || !iid) {
    const err = new Error("Proposal item ID is required.");
    err.status = 400;
    throw err;
  }
  await _sbRequireEditableProductProposal(pid, req, body);
  const current = (await _sbProposalItemRows(pid)).find((item) => String(_sbGet(item, ["id", "ID"]) ?? "").trim() === iid);
  if (!current) {
    const err = new Error("Proposal item not found.");
    err.status = 404;
    throw err;
  }
  await supabaseDb.updateById(_sbProductProposalItemsTable(), iid, {
    quantity: _sbProposalQuantity(body?.quantity || body?.qty || 1),
    updated_at: new Date().toISOString(),
  });
  await _sbTouchProductProposal(pid);
  return await _sbProductProposalById(pid, req);
}

async function _sbDeleteProductProposalItem(proposalId, itemId, body = {}, req = null) {
  const pid = String(proposalId || "").trim();
  const iid = String(itemId || "").trim();
  if (!pid || !iid) {
    const err = new Error("Proposal item ID is required.");
    err.status = 400;
    throw err;
  }
  await _sbRequireEditableProductProposal(pid, req, body);
  await supabaseDb.deleteById(_sbProductProposalItemsTable(), iid);
  await _sbTouchProductProposal(pid);
  return await _sbProductProposalById(pid, req);
}


