async function _sbAddProductProposalItemsByKit(proposalId, body = {}, req = null) {
  const kitId = String(body?.kitId || body?.kit_id || body?.id || "").trim();
  if (!kitId) {
    const err = new Error("Kit is required.");
    err.status = 400;
    throw err;
  }
  await _sbRequireEditableProductProposal(proposalId, req, body);
  const detail = await _sbProductKitById(kitId, req);
  if (!detail?.kit) {
    const err = new Error("Kit not found.");
    err.status = 404;
    throw err;
  }
  const items = Array.isArray(detail.items) ? detail.items : [];
  if (!items.length) {
    const err = new Error("This kit has no components yet.");
    err.status = 400;
    throw err;
  }
  const productMap = await _sbProductsMapById();
  let addedCount = 0;
  const kitMultiplierRaw = body?.quantity ?? body?.qty ?? body?.kitQuantity ?? body?.kit_quantity ?? 1;
  const kitMultiplier = _sbProposalQuantity(kitMultiplierRaw);
  for (const item of items) {
    const product = productMap.get(String(item.productId || "")) || { id: item.productId, name: item.productName };
    if (!product?.id) continue;
    const itemQty = _sbProposalQuantity(item.quantity || 1);
    await _sbUpsertProductProposalItem(proposalId, product, itemQty * kitMultiplier);
    addedCount += 1;
  }
  await _sbTouchProductProposal(proposalId);
  const proposal = await _sbProductProposalById(proposalId, req);
  return { ...proposal, addedCount, kit: detail.kit };
}

