async function _sbVerifyTeamMemberPassword(memberId, password) {
  const row = await _sbFindTeamMemberById(memberId);
  if (!row) return { ok: false, error: "Team member not found." };
  const stored = _sbString(_sbValueForLabel(row, "Password"));
  if (!stored) return { ok: false, error: "This team member does not have a saved password." };
  if (String(stored) !== String(password || "")) return { ok: false, error: "Invalid password." };
  return { ok: true, member: _sbSerializeProposalTeamMember(row), row };
}


async function _sbInsertOrderRowSafe(row = {}) {
  let payload = { ...(row || {}) };
  const removed = [];
  for (let attempt = 0; attempt < 10; attempt += 1) {
    try {
      return await supabaseDb.insert(_sbOrdersTable(), payload);
    } catch (error) {
      const message = String(error?.message || error?.details || error?.hint || "");
      const missingColumn =
        (message.match(/Could not find the ['"]([^'"]+)['"] column/i) || [])[1] ||
        (message.match(/column ['"]([^'"]+)['"]/i) || [])[1] ||
        "";
      if (!missingColumn || !Object.prototype.hasOwnProperty.call(payload, missingColumn)) throw error;
      delete payload[missingColumn];
      removed.push(missingColumn);
    }
  }
  const err = new Error(`Failed to create order after removing unsupported column(s): ${removed.join(", ")}`);
  err.status = 500;
  throw err;
}

async function _sbCreateOrderFromProposal(proposalId, body = {}, req = null) {
  const pid = String(proposalId || "").trim();
  const teamMemberId = String(body?.teamMemberId || body?.team_member_id || "").trim();
  const password = String(body?.password || "").trim();
  if (!pid) {
    const err = new Error("Proposal ID is required.");
    err.status = 400;
    throw err;
  }
  if (!teamMemberId || !password) {
    const err = new Error("Team member and password are required.");
    err.status = 400;
    throw err;
  }
  const verified = await _sbVerifyTeamMemberPassword(teamMemberId, password);
  if (!verified.ok) {
    const err = new Error(verified.error || "Invalid password.");
    err.status = verified.error === "Team member not found." ? 404 : 401;
    throw err;
  }
  const detail = await _sbProductProposalById(pid, req);
  if (!detail?.proposal) {
    const err = new Error("Proposal not found.");
    err.status = 404;
    throw err;
  }
  const items = Array.isArray(detail.items) ? detail.items : [];
  if (!items.length) {
    const err = new Error("This proposal has no components yet.");
    err.status = 400;
    throw err;
  }
  const productMap = await _sbProductsMapById();
  const orderNumber = await _sbNextOrderNumber();
  const now = new Date().toISOString();
  const created = [];
  for (const item of items) {
    const product = productMap.get(String(item.productId || "")) || {};
    const qty = _sbProposalQuantity(item.quantity || 1);
    const row = {
      reason: detail.proposal.name || "Proposal",
      order_number: orderNumber,
      order_type: _canonicalOrderTypeLabel("Request Products") || "Request Products",
      notion_created_time: now,
      product_name: product.name || item.productName || "Unknown Product",
      product_url: product.url || null,
      unit_price: Number.isFinite(Number(product.unitPrice)) ? Number(product.unitPrice) : null,
      quantity_requested: qty,
      quantity_progress: qty,
      quantity_received_by_operations: 0,
      quantity_remaining: qty,
      status: "Under Supervision",
      sv_approval: null,
      team_member_id: verified.member.id || null,
      team_member_name: verified.member.name || null,
      issue_description: `Created from proposal: ${detail.proposal.name || "Proposal"}`,
      supervisor: null,
      person_received_by_operations: null,
      created_by_name: String(req?.session?.username || "").trim() || null,
      created_by_id: String(req?.session?.userSupabaseId || "").trim() || null,
    };
    created.push(await _sbInsertOrderRowSafe(row));
  }
  await _sbInvalidateOrdersCaches();
  return { orderNumber, orderId: `ORD-${orderNumber}`, count: created.length, member: verified.member };
}

async function _sbProductsMapById() {
  const products = await _sbProductsList();
  return new Map(products.map((p) => [String(p.id), p]));
}

async function _sbNextOrderNumber() {
  const rows = await supabaseDb.select(_sbOrdersTable(), {
    select: "order_number",
    order: "order_number.desc",
    limit: 1,
  });
  const n = Array.isArray(rows) && rows[0] ? _sbOrderNum(rows[0].order_number) : null;
  return Number.isFinite(n) ? n + 1 : 1;
}

async function _sbCreateOrdersFromCart(req, cleanProducts = [], orderType = "") {
  const productMap = await _sbProductsMapById();
  const orderNumber = await _sbNextOrderNumber();
  const now = new Date().toISOString();
  const createdByName = String(req.session?.username || "").trim() || null;
  const rows = [];
  for (const product of cleanProducts || []) {
    const info = productMap.get(String(product.id)) || {};
    const qty = Number(product.quantity) || 0;
    rows.push({
      reason: String(product.reason || "").trim() || null,
      order_number: orderNumber,
      order_type: _canonicalOrderTypeLabel(orderType) || orderType || null,
      notion_created_time: now,
      product_name: info.name || String(product.name || product.id || "Unknown Product"),
      product_url: info.url || null,
      unit_price: Number.isFinite(Number(info.unitPrice)) ? Number(info.unitPrice) : null,
      quantity_requested: qty,
      quantity_progress: qty,
      quantity_received_by_operations: 0,
      quantity_remaining: qty,
      status: "Under Supervision",
      sv_approval: null,
      team_member_name: createdByName,
      issue_description: String(product.issueDescription || "").trim() || null,
      supervisor: null,
      person_received_by_operations: null,
    });
  }
  const created = [];
  for (const row of rows) {
    created.push(await supabaseDb.insert(_sbOrdersTable(), row));
  }
  await _sbInvalidateOrdersCaches();
  return created.map(_sbSerializeOrderRow);
}

async function _sbInvalidateProductsCaches() {
  await Promise.all([
    cacheDel("cache:api:components:supabase:v1"),
  ]);
}



// توسيع الأسماء للواجهة حتى لا يحصل تضارب aliases
function expandAllowedForUI(list = []) {
  const set = new Set((list || []).map((s) => String(s)));
  if (set.has("Requested Orders") || set.has("Schools Requested Orders")) {
    set.add("Requested Orders");
    set.add("Schools Requested Orders");
  }
  if (set.has("Maintenance Orders")) {
    set.add("Maintenance Orders");
  }  if (set.has("Funds")) {
    set.add("Funds");
  }
  if (set.has("Products")) {
    set.add("Products");
    set.add("Product");
    set.add("Components");
    set.add("/products");
  }
  if (set.has("Proposals")) {
    set.add("Proposals");
    set.add("Kits");
    set.add("Saved Quotations");
    set.add("/proposals");
  }
  if (set.has("Expenses")) {
    set.add("Expenses");
  }
  if (set.has("Expenses Users")) {
    set.add("Expenses Users");
  }  if (set.has("Tasks")) {
    set.add("Tasks");
  }
  if (set.has("Mail") || set.has("Messages") || set.has("Emails")) {
    set.add("Mail");
    set.add("Email");
    set.add("Emails");
    set.add("Messages");
    set.add("/messages");
    set.add("/emails");
  }
  if (set.has(USER_ACCESS_PAGE_NAME)) {
    set.add(USER_ACCESS_PAGE_NAME);
    set.add("User Access");
    set.add("Team Members");
    set.add("/user-access");
  }
  return Array.from(set);
}

function extractAllowedPages(props = {}) {
  // Try known property names first (case-sensitive)
  let candidates =
    props.Pages?.multi_select ||
    props["Allowed Pages"]?.multi_select ||
    props["Allowed pages"]?.multi_select ||
    props["Pages Allowed"]?.multi_select ||
    props["Access Pages"]?.multi_select ||
    [];

  // If still empty, look for any multi_select prop whose name matches /allowed.*pages|pages.*allowed/i
  if (!Array.isArray(candidates) || candidates.length === 0) {
    for (const [key, val] of Object.entries(props || {})) {
      if (val && val.type === "multi_select" && /allowed.*pages|pages.*allowed/i.test(String(key))) {
        candidates = val.multi_select || [];
        break;
      }
    }
  }

  const names = Array.isArray(candidates)
    ? candidates.map((x) => x?.name).filter(Boolean)
    : [];
  const allowed = normalizePages(names);
  return allowed;
}

function firstAllowedPath(allowed = []) {
  const list = Array.isArray(allowed) ? allowed : [];

  // Prefer a deterministic order for the best UX
  if (list.includes("Current Orders")) return "/orders";
  if (list.includes("Requested Orders")) return "/orders/requested";
  if (list.includes("Maintenance Orders")) return "/orders/maintenance-orders";
  if (list.includes("Orders Review")) return "/orders/sv-orders";
  if (list.includes("Create New Order")) return "/orders/new";
  if (list.includes("Stocktaking")) return "/stocktaking";
  if (list.includes("Products")) return "/products";
  if (list.includes("Proposals")) return "/proposals";
  if (list.includes("Tasks")) return "/tasks";
  if (list.includes("Mail") || list.includes("Messages") || list.includes("Emails")) return "/messages";
  if (list.includes("B2B")) return "/b2b";
  if (list.includes("Expenses Users")) return "/expenses/users";
  if (list.includes("Expenses")) return "/expenses";
  if (list.includes(USER_ACCESS_PAGE_NAME)) return "/user-access";

  // Fallback (important): avoid redirect loops if user only has a page we don't recognize.
  // /account does NOT require page permission, so it is a safe landing page.
  return "/account";
}

